window.DIGEST_ARCHIVE=window.DIGEST_ARCHIVE||{};window.DIGEST_ARCHIVE["2026-08-10"]={"date": "2026-08-10", "dateKR": "2026년 8월 10일", "dateEN": "10 August 2026", "total": 89, "sections": [{"code": "TOP", "type": "news", "kTitle": "Section 1. 주요 뉴스", "eTitle": "Section 1. Top News", "items": [{"code": "TOP", "title": "Minsheng, Shell 지원 MR 탱커 프로그램 11척으로 확대", "src": "Splash247", "date": "2026-08-10", "kSum": "민성금융리스(Minsheng Financial Leasing)가 광저우조선국제(GSI)에서 진행 중인 Shell 지원 MR 탱커 프로그램을 11척으로 확대했다. 기존 6척 시리즈 건조가 시작되는 가운데 5척을 추가 발주한 것으로, 계약은 Minsheng·GSI·중국선박무역(CSTC)이 체결했다.", "eSum": "Minsheng Financial Leasing has expanded its Shell-backed MR tanker programme at Guangzhou Shipyard International to 11 ships, adding five newbuildings as construction starts on the original six-vessel series. The contracts were signed by Minsheng, GSI and China Shipbuilding Trading.", "kImp": "메이저 정유사 Shell이 장기 용선으로 뒷받침하는 대형 프로덕트 탱커 발주로, 중국 조선소의 수주 잔량과 정제품 운송 선대 확충 흐름을 보여준다.", "eImp": "A major oil company's long-term backing for a large product-tanker order signals continued Chinese yard orderbook strength and clean-product fleet renewal.", "url": "https://splash247.com/minsheng-expands-shell-backed-mr-tanker-programme-to-11-newbuilds/"}, {"code": "TOP", "title": "Sumitomo, 켈틱해 대형 부유식 해상풍력 프로젝트 지분 인수", "src": "Splash247", "date": "2026-08-10", "kSum": "일본 스미토모상사(Sumitomo Corporation)가 EDF와 아일랜드 ESB가 켈틱해에서 개발 중인 Gwynt Glas 해상풍력단지 지분 33.3%를 인수했다. 스미토모의 첫 부유식 해상풍력 프로젝트 참여다.", "eSum": "Japan's Sumitomo Corporation has bought a 33.3% equity interest in the Gwynt Glas offshore wind farm, developed by EDF and Electricity Supply Board (ESB) in the Celtic Sea. The acquisition marks Sumitomo's first participation in a floating offshore wind project.", "kImp": "일본 대형 종합상사의 부유식 해상풍력 진출로, 켈틱해가 차세대 심해 풍력 개발 거점으로 부상하고 해상풍력 설치·지원선 수요 확대가 예상된다.", "eImp": "A major Japanese trading house entering floating wind underscores the Celtic Sea as a deepwater development hub and points to growing demand for installation and support vessels.", "url": "https://splash247.com/sumitomo-buys-into-major-celtic-sea-floating-wind-project/"}, {"code": "TOP", "title": "머스크, 훈련 자회사 Maersk Training을 OpenGate에 매각", "src": "Splash247", "date": "2026-08-10", "kSum": "머스크(Maersk)가 훈련 자회사 Maersk Training과 그 산하 Maersk H2S를 사모펀드 OpenGate Capital에 매각하기로 합의했다. 비핵심 사업 정리를 통해 통합 물류 사업에 집중하려는 움직임이다.", "eSum": "Maersk has agreed to sell Maersk Training and its subsidiary Maersk H2S to private equity firm OpenGate Capital, continuing its divestment of non-core units to focus on integrated logistics.", "kImp": "글로벌 1위권 해운·물류 그룹의 사업 포트폴리오 재편 사례로, 선원·산업 훈련 서비스 시장의 소유구조 변화를 시사한다.", "eImp": "A portfolio reshaping move by a top global shipping and logistics group, signaling ownership shifts in the seafarer and industrial training services market.", "url": "https://splash247.com/maersk-sells-training-arm-to-opengate/"}, {"code": "TOP", "title": "Brookfield, Torm 지분 19.86% 간접 지배로 편입", "src": "Splash247", "date": "2026-08-10", "kSum": "브룩필드(Brookfield)가 덴마크 프로덕트 탱커 선사 Torm의 지분 19.86%를 간접적으로 지배하게 됐다. 관련 자산 인수를 통해 지분이 승계된 형태다.", "eSum": "Brookfield has taken indirect control of a 19.86% stake in Danish product tanker owner Torm, the holding passing to the group through a related asset acquisition.", "kImp": "대형 인프라·자산운용사가 상장 탱커 선사의 최대주주급 지분을 확보하면서, 금융투자자의 해운 자산 지배력 확대 추세를 보여준다.", "eImp": "A major infrastructure and asset manager acquiring a top-tier stake in a listed tanker owner illustrates the growing influence of financial investors over shipping assets.", "url": "https://splash247.com/brookfield-inherits-major-torm-stake/"}, {"code": "TOP", "title": "Cadeler, 풍력설치선 2척 9.3억 달러 규모 신조 계약", "src": "Splash247", "date": "2026-08-10", "kSum": "해상풍력 설치선 선두주자 Cadeler가 중국 COSCO조선과 신형 T-Class 풍력설치선(WTIV) 2척 건조 확정 계약을 체결했다. 계약 규모는 9억3,000만 달러다.", "eSum": "Offshore wind installation heavyweight Cadeler has signed firm contracts with COSCO Shipping for two new T-Class wind turbine installation vessels in a deal worth $930m.", "kImp": "대형 차세대 풍력설치선 발주로 해상풍력 대형 터빈 설치 역량 확충이 이어지고 있음을 보여주며, 중국 조선소의 고부가 특수선 수주 확대를 확인시킨다.", "eImp": "A large next-generation WTIV order shows continued build-out of large-turbine installation capacity and confirms Chinese yards winning high-value specialised tonnage.", "url": "https://splash247.com/cadeler-signs-930m-deal-for-two-new-wind-installation-vessels/"}, {"code": "TOP", "title": "중국의 석탄 증설, 벌크선 수요에 새 안전판 제공", "src": "Splash247", "date": "2026-08-10", "kSum": "미·이란 전쟁 이후 석탄이 중국의 핵심 에너지 완충재로 부상하며 발전 전략을 뒷받침하고 있다. 중국의 대규모 석탄화력 증설은 건화물(드라이벌크) 해운에 견조한 수요 지지 요인으로 작용하고 있다고 Splash247이 분석했다.", "eSum": "Coal has emerged as one of China's key energy buffers in the wake of the US-Iran war, reinforcing a power-generation strategy that remains supportive for dry bulk shipping despite Beijing's vast renewable push.", "kImp": "세계 최대 석탄 수입국의 정책 방향이 케이프사이즈·파나막스 등 벌크선 물동량과 운임 전망에 직접적 영향을 미친다.", "eImp": "The policy direction of the world's largest coal importer directly affects dry bulk volumes and rate prospects for capesize and panamax tonnage.", "url": "https://splash247.com/chinas-coal-buildout-offers-fresh-ballast-for-dry-bulk/"}, {"code": "TOP", "title": "중국 Sea Legend, 첫 정기 '빙상 실크로드' 컨테이너 서비스 임박", "src": "The Maritime Executive", "date": "2026-08-10", "kSum": "중국 선사 Sea Legend Line이 러시아 북극항로(NSR)를 이용한 정기 컨테이너 서비스 개시를 앞두고 있다. 러시아 로사톰(Rosatom)이 2026년 NSR 시즌 허가 발급을 완료했다고 밝히면서, 사상 첫 정기 북극 컨테이너 항로가 될 전망이다.", "eSum": "China's Sea Legend Line is poised to launch a regular container route along Russia's Northern Sea Route, billed as the first regular Arctic container service. Rosatom said it has completed issuing permits for the 2026 NSR season.", "kImp": "아시아-유럽 간 최단 대체 항로로서 북극항로 정기 운항 상용화가 가시화되며, 수에즈 우회 및 지정학·환경 논란을 함께 촉발할 사안이다.", "eImp": "Regular Arctic container operations move toward commercialization as a shortest alternative Asia-Europe route, raising Suez-diversion, geopolitical and environmental questions.", "url": "https://maritime-executive.com/article/china-s-sea-legend-poised-to-launch-first-regular-ice-silk-road-service"}, {"code": "TOP", "title": "우크라이나, 미국 압박에 카스피 파이프라인 공격 중단 합의", "src": "The Maritime Executive", "date": "2026-08-10", "kSum": "미국의 압박을 받은 우크라이나가 흑해 카스피 파이프라인 컨소시엄(CPC) 관련 외국적 탱커에 대한 공격을 중단하기로 합의한 것으로 전해졌다. 최근 드론 공격으로 CPC 탱커 운임이 급등한 바 있다.", "eSum": "Under pressure from the United States, Ukraine has reportedly agreed to stop attacking foreign-flag tankers linked to the Caspian Pipeline Consortium (CPC) in the Black Sea, after recent drone strikes sent CPC tanker rates soaring.", "kImp": "흑해 원유 수출 안정과 카자흐스탄산 원유 흐름 재개에 직결되는 사안으로, 탱커 운임·보험료·항로 리스크를 크게 좌우한다.", "eImp": "Directly tied to stabilizing Black Sea crude exports and restoring Kazakh oil flows, materially affecting tanker rates, insurance premiums and routing risk.", "url": "https://maritime-executive.com/article/ukraine-agrees-under-u-s-pressure-to-stop-attacks-on-caspian-pipeline"}, {"code": "TOP", "title": "머스크·하파그로이드, Gemini 추가 노선 수에즈 복귀", "src": "The Maritime Executive", "date": "2026-08-10", "kSum": "머스크(Maersk)와 하파그로이드(Hapag-Lloyd)가 Gemini 협력체의 추가 노선을 수에즈 운하 경유로 복귀시킨다고 밝혔다. 컨테이너선의 홍해·수에즈 항로 점진적 복귀가 이어지고 있다.", "eSum": "Maersk and Hapag-Lloyd reported that an additional Gemini Cooperation route is returning to the Suez Canal, continuing the gradual transition of containerships back to the Red Sea and Suez.", "kImp": "홍해 리스크 완화 인식 속 주요 얼라이언스의 수에즈 복귀 확대는 아시아-유럽 항로 스케줄·선복·운임에 직접적 영향을 준다.", "eImp": "Expanding Suez returns by a major alliance, amid easing Red Sea risk perception, directly affects Asia-Europe schedules, capacity and freight rates.", "url": "https://maritime-executive.com/article/maersk-and-hapag-lloyd-restore-another-gemini-route-to-suez"}, {"code": "TOP", "title": "KCC, 3세대 CABU 겸용선 마지막 선박 인도받아", "src": "MarineLink", "date": "2026-08-09", "kSum": "클라베네스 겸용선사(Klaveness Combination Carriers, KCC)가 중국 뉴양쯔조선소에서 3세대 CABU 겸용선의 세 번째이자 마지막 선박 MV Baltazar를 인도받았다. 이 선박은 KCC 선대 최초로 풍력보조추진 시스템을 탑재했으며, 인도로 KCC 겸용선 선대는 19척으로 늘었다.", "eSum": "Klaveness Combination Carriers (KCC) took delivery of MV Baltazar, its third and final third-generation CABU vessel, from New Yangzi Shipyard in China. The vessel carries the first wind-assisted propulsion system in KCC's fleet, bringing the fleet to 19 combination carriers.", "kImp": "건화물·액체화물을 겸용 운송하는 겸용선의 선대 확충과 풍력보조추진 도입은 공선 항해 감축과 탄소 효율 개선이라는 이중 이점을 보여준다.", "eImp": "Fleet growth in dual dry/wet combination carriers plus wind-assisted propulsion demonstrates the twin benefits of reducing ballast voyages and improving carbon efficiency.", "url": "https://www.marinelink.com/news/kcc-takes-delivery-final-cabu-iii-541922"}]}, {"code": "ACC", "type": "accident", "kTitle": "Section 2. 해양사고", "eTitle": "Section 2. Accidents", "items": [{"code": "ACC", "title": "NTSB, 뉴욕시 슬러지 탱커 Hunts Point 치명적 폭발 원인으로 미승인 열간작업 지목", "src": "gCaptain", "date": "2026-08-10", "kSum": "미국 NTSB가 2025년 5월 26일 뉴욕시 하수처리 슬러지 운반선 Hunts Point(2014년 건조, 289피트)에서 발생한 폭발 사고 조사보고서를 공개했다. 맨해튼 노스리버 하수처리장에 접안 중, 기관장이 프로판 토치로 해치 커버의 부러진 볼트를 제거하려다 폭발이 발생해 기관장 1명이 사망하고 2명이 부상했으며 선박 손상액은 약 1,000만 달러로 추정된다.", "eSum": "The US NTSB released its report on the May 26, 2025 explosion aboard the New York City sewage-sludge tanker Hunts Point (built 2014, 289ft). While docked at Manhattan's North River treatment plant, the chief engineer used a propane torch to remove broken bolts from a hatch cover, triggering a blast that killed him and injured two others, with vessel damage estimated at about $10 million.", "kCause": "미승인 열간작업(토치 사용)이 화물창 내 가연성 메탄가스를 점화한 것이 직접 원인이다. DEP 절차는 갑판 화기 사용을 금지하고 열간작업 허가서를 요구했으나 허가서가 발급되지 않았고, 선장이 기관장에게 탱크 인근 토치 사용을 하지 말라고 특별히 지시했음에도 무시됐다. 오랫동안 시행하지 않은 '이니지 감소' 작업 중 녹슬어 고착된 플러그·볼트를 제거하려다 사고로 이어졌다.", "eCause": "Unapproved hot work (torch use) ignited flammable methane gas in the hold. DEP procedures prohibited open flame on deck and required a hot-work permit, none of which was issued; the master had specifically instructed the chief engineer not to use a torch near the tanks, but the warning was ignored during an infrequently performed 'innage reduction' task involving rusted, seized plugs and bolts.", "kLes": "밀폐구역·가연성 가스가 존재하는 화물 인근에서는 반드시 열간작업 허가와 가스 측정을 선행해야 하며, 토치 대신 위험이 없는 대체 공구를 사용해야 한다. NTSB는 기관장이 다른 공구를 썼다면 사고를 막을 수 있었다고 지적했다. 사고 후 DEP는 열간작업·슬러지 위험 절차 재검토 지침을 하달했다.", "eLes": "Hot-work permits and gas testing must precede any work near cargo containing flammable gas, and non-sparking alternative tools should replace torches. The NTSB noted the casualty could have been prevented had other available tools been used; DEP has since ordered a review of hot-work and sludge-hazard procedures.", "url": "https://gcaptain.com/ntsb-blames-unapproved-hot-work-for-deadly-nyc-sludge-tanker-explosion/"}, {"code": "ACC", "title": "MSC 및 기관장, 2024년 찰스턴 폭주 컨테이너선 사고로 유죄·벌금", "src": "The Maritime Executive", "date": "2026-08-10", "kSum": "2024년 미국 찰스턴 항에서 전속력으로 통제 불능 상태(16~17노트)로 항내를 질주한 컨테이너선 MSC Michigan VII(2000년 건조, 6,648TEU)의 운영사 MSC Shipmanagement와 기관장이 8월 10일 법정에서 유죄를 인정했다. MSC는 600만 달러 벌금과 4년 보호관찰, 근본원인 분석 의무를 부과받았고, 필리핀 국적 기관장 Fernando San Diego San Juan은 2,000달러 벌금형을 받았다.", "eSum": "MSC Shipmanagement, operator of the containership MSC Michigan VII (built 2000, 6,648 TEU) that took a full-speed 16-17 knot runaway trip through Charleston harbor in 2024, and the vessel's chief engineer pleaded guilty in court on August 10. MSC was fined $6 million with four years' probation and a mandatory root-cause analysis; Filipino chief engineer Fernando San Diego San Juan was fined $2,000.", "kCause": "거버너와 연료랙을 잇는 링키지 로드가 분리되어 주기관이 전속으로 돌면서 속도 제어 불능에 빠진 것이 직접 원인이다. 자격 없는 기관부 선원이 원하는 RPM을 맞추려 링키지 로드의 양단 너트를 풀고 잠금 와셔를 제거해 수동 조정해 온 관행이 로드 이탈을 유발했다. 회사는 위험 상태를 보고하지 않았고 조사 방해도 있었다.", "eCause": "The linkage rod between the governor and fuel rack disconnected, leaving the main engine running at full speed with no speed control. Unqualified engine-department crew had been manually adjusting the rod by loosening the nuts and removing the locking washers to hit ordered RPMs, causing the rod to back out; the company failed to report the hazardous condition and obstructed the investigation.", "kLes": "거버너·링키지 등 안전 핵심 기관 부품은 자격을 갖춘 기술자만 조정해야 하며, 임시방편적 수동 조정은 치명적 통제 상실로 이어질 수 있다. 위험 상태의 정직한 보고와 잠금장치 유지가 필수이며, 조사 방해와 은폐는 형사처벌로 이어진다.", "eLes": "Safety-critical machinery such as governors and linkages must only be adjusted by qualified technicians; makeshift manual adjustment can cause catastrophic loss of control. Honest reporting of hazardous conditions and retention of locking devices are essential, and obstruction or cover-up leads to criminal penalties.", "url": "https://maritime-executive.com/article/msc-and-chief-engineer-guilty-and-fined-for-2024-runaway-boxship-incident"}, {"code": "ACC", "title": "COSCO 운영 자동차운반선 Min Jiang Kou 기관실 화재…선원 22명 구조", "src": "Seatrade Maritime", "date": "2026-08-10", "kSum": "마셜제도 선적 COSCO 운영 자동차운반선(PCTC) Min Jiang Kou가 코스타리카 남쪽 약 630마일 해상에서 기관실 화재로 조난했다. 8월 8일 0109시 USCG가 조난신호를 접수했고, 선원들이 CO2 소화장치를 작동했으나 연기가 심해지자 선장을 제외한 전원이 구명정으로 퇴선했다. 인근 벌크선 Jin Hai Ping이 선원 22명 전원을 구조해 일본 아키타로 이송 중이다.", "eSum": "The Marshall Islands-flagged, COSCO-managed car carrier (PCTC) Min Jiang Kou suffered an engine-room fire about 630 miles south of Costa Rica. The USCG received a distress call at 0109 on August 8; the crew activated the CO2 system but worsening smoke forced all but the captain to abandon ship into lifeboats. Nearby bulker Jin Hai Ping recovered all 22 mariners and is transporting them to Akita, Japan.", "kCause": "화재는 기관실에서 발생했으며 정확한 발화 원인은 조사 중이다(추정). 한 업계 소식통은 이 선박이 중국산 전기차를 적재했을 가능성을 제기했으며, 리튬이온 배터리의 열폭주가 화재·유독가스 위험을 키울 수 있다고 지적했다.", "eCause": "The fire originated in the engine room and its exact ignition source is under investigation (presumed). One industry source suggested the ship may have loaded Chinese-built electric vehicles, whose lithium-ion batteries can pose thermal-runaway, fire and toxic-fume risks.", "kLes": "CO2 고정식 소화장치로 초기 진화가 어려울 경우 신속한 퇴선 판단과 인근 선박의 조난 응답이 인명 구조의 관건이다. EV·리튬이온 배터리 화물 운반선의 열폭주 위험 관리와 국제 공조 구조 체계의 중요성이 재확인됐다.", "eLes": "When fixed CO2 systems fail to contain a blaze, timely abandon-ship decisions and neighbouring vessels' distress response are decisive for saving lives; the case reaffirms the importance of managing EV/lithium-ion thermal-runaway risk and of coordinated international rescue.", "url": "https://www.seatrade-maritime.com/accidents/22-crew-rescued-from-cosco-managed-car-carrier-after-fire"}, {"code": "ACC", "title": "NTSB, 휴스턴 수로 치명적 충돌 원인으로 도선사 사적 통화 지목", "src": "gCaptain", "date": "2026-08-06", "kSum": "미국 NTSB가 2024년 7월 19일 휴스턴 선박수로 린치버그 인근에서 발생한 벌크선 Yangze 7(656피트)과 예인선 Miss Peggy 충돌 사고 조사보고서를 공개했다. Miss Peggy는 충돌 후 우현으로 전복·침몰해 승선 5명 중 1명이 사망하고 1명이 중상을 입었으며, 기름 유출과 함께 피해·정화 비용이 약 370만 달러로 추정된다.", "eSum": "The US NTSB released its report on the July 19, 2024 collision near Lynchburg in the Houston Ship Channel between the bulk carrier Yangze 7 (656ft) and the towing vessel Miss Peggy. Miss Peggy capsized and sank to starboard, killing one of five aboard and seriously injuring another, with an oil release and estimated damage/cleanup costs of about $3.7 million.", "kCause": "벌크선을 지휘하던 휴스턴 도선사가 충돌 직전 39분간 다른 도선사와 업무와 무관한 개인 통화를 하며 경계를 소홀히 한 것이 주요 원인이다. Yangze 7 선교팀은 도선사의 사적 통화를 인지하고도 개입하지 않았고(부실한 BRM), Miss Peggy 선장도 후방에서 접근하는 벌크선을 발견하지 못하는 등 세 당사자 모두 적절한 경계를 유지하지 못해 상황인식을 상실했다.", "eCause": "The Houston pilot directing the bulker had been engaged in a 39-minute non-operational personal phone call with another pilot right before impact, losing awareness. The Yangze 7 bridge team failed to intervene despite noticing it (poor BRM), and the Miss Peggy captain did not detect the bulker approaching from astern; all three parties lost situational awareness through failure to keep a proper lookout.", "kLes": "선박 조종 중 업무와 무관한 개인 전자기기 사용을 금지하는 명확한 정책이 필요하며, 선교팀은 도선사의 부적절 행위에 적극 개입해야 한다(BRM). NTSB는 USCG에 수로 조종자의 비업무용 개인기기 사용 금지를, 미국도선사협회에 관련 지침 마련을 권고했다. 2009~2024년 최소 10건의 사고가 개인기기 주의분산과 연관됐다.", "eLes": "Clear policies banning non-operational personal device use while directing vessels are needed, and bridge teams must actively challenge a pilot's unsafe conduct (BRM). The NTSB recommended the USCG prohibit such device use by anyone conning vessels and urged the American Pilots' Association to issue guidance; distraction featured in at least 10 marine accidents from 2009-2024.", "url": "https://gcaptain.com/ntsb-pilots-personal-phone-call-contributed-to-fatal-houston-ship-channel-collision/"}]}, {"code": "PSC", "type": "news", "kTitle": "Section 3. 항만국통제", "eTitle": "Section 3. Port State Control", "items": [{"code": "PSC", "title": "Joint Press Release on the Concentrated Inspection Campaign (CIC) on Cargo Securing", "src": "TOKYO MOU", "date": "2026-08-03", "kSum": "도쿄MOU(Tokyo MOU)와 파리MOU(Paris MOU)가 2026년 9월 1일부터 11월 30일까지 화물 고박(cargo securing)을 주제로 공동 집중점검캠페인(CIC)을 시행한다고 공동 보도자료를 통해 발표했다. 항만국통제관(PSCO)은 화물단위·화물운송단위의 적재·적부·고박에 관한 SOLAS 준수 여부를 확인하는 10개 문항 설문지를 적용하며, 이 중 7개 문항은 억류 사유가 될 수 있다.", "eSum": "The Tokyo and Paris MoUs issued a joint press release announcing a Concentrated Inspection Campaign (CIC) on Cargo Securing from 1 September to 30 November 2026. PSC officers will apply a ten-question questionnaire checking SOLAS compliance on the loading, stowage and securing of cargo units and cargo transport units, of which seven questions can constitute grounds for detention.", "kImp": "9~11월 파리·도쿄MOU 항만에 기항하는 모든 대상 선박이 고박 설문 점검을 받게 되므로, 선사는 승인된 화물고박매뉴얼(CSM)과 장비·기록 상태를 사전 점검해야 한다.", "eImp": "Every eligible vessel calling at Paris or Tokyo MoU ports from September to November will be screened against the cargo-securing questionnaire, so operators must verify their approved Cargo Securing Manual, equipment and records in advance.", "url": "https://www.tokyo-mou.org/wp/wp-content/uploads/Joint-Press-Release-on-CIC-on-Cargo-Securing-all.pdf"}, {"code": "PSC", "title": "Port State Control – CIC 2026 official questionnaire now published", "src": "DNV", "date": "2026-08-05", "kSum": "DNV는 파리·도쿄MOU가 8월 3일 보도자료를 통해 2026년 화물 고박 CIC 공식 설문지를 공개했다고 전했다. 설문지는 고박 요건 준수를 확인하는 10개 문항으로 구성되며 그중 7개는 억류 사유가 될 수 있고, 문항 1·6·10a/10b는 억류 대상이 아닌 결함으로만 처리된다. 캠페인은 9월 1일 시작해 9~11월 정기 PSC 점검에 통합된다.", "eSum": "DNV reports that the Paris and Tokyo MoUs published the official questionnaire for the 2026 Cargo Securing CIC via their 3 August press release. The questionnaire contains ten questions verifying cargo-securing compliance, seven of which may be grounds for detention, while questions 1, 6 and 10a/10b result only in non-detainable deficiencies. The campaign starts 1 September and is embedded in routine PSC inspections from September to November.", "kImp": "공식 설문 문항과 억류 판단 기준이 사전 공개돼 선사가 억류 위험 항목을 겨냥한 사전 자체점검으로 대비할 수 있다.", "eImp": "Advance publication of the exact questions and detention criteria lets operators run targeted self-inspections focused on the detainable items before arrival.", "url": "https://www.dnv.com/news/2026/port-state-control-cic-2026-official-questionnaire-now-published/"}, {"code": "PSC", "title": "Cargo Securing in Focus: Preparing for the 2026 PSC CIC", "src": "NORTHSTANDARD", "date": "2026-08-05", "kSum": "노스스탠다드(NorthStandard)는 P&I 관점에서 2026년 파리·도쿄MOU 화물 고박 CIC 대비 방안을 제시했다. 고박 결함은 종종 컨테이너 적재 붕괴나 화물 유실 등 더 큰 운영상 위험과 P&I 클레임으로 이어진다며, 승인된 CSM 최신본 비치, 고박장비 정비, VGM·VCG 검증, 선원 숙지도 등을 점검하도록 권고했다. PSC 점검이 서류를 넘어 실제 이행 여부와 선원 이해도를 확인하는 방향으로 강화되고 있다고 강조했다.", "eSum": "NorthStandard offers a P&I-focused guide to preparing for the 2026 Paris/Tokyo MoU Cargo Securing CIC. It notes that cargo-securing shortcomings often reflect wider operational risks such as container stack collapse and cargo loss, leading to P&I claims, and recommends verifying the latest approved CSM, maintaining lashing gear, confirming VGM/VCG and ensuring crew familiarity. It stresses that PSC inspections increasingly move beyond paperwork to test real implementation and crew understanding.", "kImp": "고박 CIC가 단순 점검 통과가 아니라 화물·선원·환경 보호와 P&I 클레임 예방으로 직결되므로 선사는 서류뿐 아니라 실제 이행 체계를 강화해야 한다.", "eImp": "The CIC is framed as more than an inspection to pass, tying cargo securing directly to crew and cargo safety and P&I claim prevention, pushing operators to strengthen practical implementation, not just documentation.", "url": "https://north-standard.com/insights-and-resources/resources/articles/cargo-securing-in-focus-preparing-for-the-2026-psc-cic"}]}, {"code": "PCTC", "type": "news", "kTitle": "Section 4. 자동차운반선", "eTitle": "Section 4. PCTC / Car Carriers", "items": [{"code": "PCTC", "title": "COSCO Car Carrier Catches Fire off Costa Rica, 22 Seafarers Rescued", "src": "maritime-executive.com", "date": "2026-08-09", "kSum": "COSCO의 자동차운반선(PCTC) 민장커우(Min Jiang Kou)가 8월 6일 코스타리카 남서쪽 약 600해리 태평양 해상에서 기관실 화재를 겪었다. CO2 소화장치로 일시 진화했으나 연기가 심해지자 선장을 제외한 승무원이 구명정으로 퇴선했고, 인근 벌크선 진하이핑(Jin Hai Ping)과 탱커 데구(Degu)가 22명 전원을 구조했다. 선박은 미국 살보업체 리졸브 마린(Resolve Marine)과 후속 인양을 협의 중이다.", "eSum": "COSCO's PCTC Min Jiang Kou suffered an engine-room fire on 6 August about 600 nm southwest of Costa Rica in the Eastern Pacific. After CO2 flooding initially contained the blaze, worsening smoke forced the crew (except the master) to abandon ship, and the bulker Jin Hai Ping and tanker Degu rescued all 22 seafarers. The vessel is coordinating with US salvor Resolve Marine on recovery.", "kImp": "대형 PCTC 기관실 화재와 전원 퇴선은 자동차운반선 화재 리스크와 원양 구조 대응 역량을 다시 부각시킨다.", "eImp": "A major PCTC engine-room fire and full abandonment underscore persistent car-carrier fire risk and the importance of deep-ocean rescue coordination.", "url": "https://maritime-executive.com/article/cosco-car-carrier-catches-fire-off-costa-rica-22-seafarers-rescued"}, {"code": "PCTC", "title": "Fire ignites on car carrier off Costa Rica; all on board rescued", "src": "bairdmaritime.com", "date": "2026-08-10", "kSum": "미국 해안경비대(USCG)가 8월 6일 코스타리카 남쪽 약 630마일 해상에서 마셜제도 선적 PCTC 민장커우(Min Jiang Kou)의 기관실 화재 조난신호를 접수하고 구조를 조율했다. 승무원 22명은 구명정 퇴선 후 선한 사마리아인 선박 진하이핑(Jin Hai Ping)에 전원 구조돼 일본 아키타로 이송됐다. 환경오염은 보고되지 않았으며 리졸브 마린(Resolve Marine)이 수리를 지원한다.", "eSum": "The US Coast Guard coordinated the rescue after receiving a distress alert from the Marshall Islands-flagged PCTC Min Jiang Kou over an engine-room fire some 630 miles south of Costa Rica on 6 August. All 22 crew abandoned ship and were recovered by the good Samaritan vessel Jin Hai Ping, which is taking them to Akita, Japan. No environmental impact was reported, with Resolve Marine assisting on repairs.", "kImp": "AMVER 기반 상선 상호구조가 원양 자동차운반선 사고에서 인명 손실을 막은 사례로, 선대 안전관리에 시사점을 준다.", "eImp": "The AMVER-enabled merchant rescue prevented loss of life in a remote car-carrier casualty, offering lessons for fleet safety management.", "url": "https://www.bairdmaritime.com/security/incidents/accidents/fire-ignites-on-car-carrier-off-costa-rica-all-on-board-rescued"}]}, {"code": "WW", "type": "news", "kTitle": "Section 5. 발레니우스 빌헬름센", "eTitle": "Section 5. Wallenius Wilhelmsen", "items": [{"code": "WW", "title": "Wallenius Wilhelmsen: Invitation to Q2 2026 results presentation", "src": "Wallenius Wilhelmsen", "date": "2026-08-03", "kSum": "발레니우스 빌헬름센(Wallenius Wilhelmsen)이 8월 3일 오슬로 증권거래소 공시를 통해 2026년 2분기 실적 발표회를 2026년 8월 11일에 개최한다고 안내했다. 이는 8월 10일 기준으로 2분기 실적이 아직 공식 발표되지 않았음을 의미한다. CEO 라세 크리스토페르센(Lasse Kristoffersen) 등 경영진이 실적을 설명할 예정이다.", "eSum": "On 3 August, Wallenius Wilhelmsen issued an Oslo Bors notice inviting investors, analysts and media to its Q2 2026 results presentation, scheduled for 11 August 2026. This confirms the Q2 2026 figures had not yet been released as of 10 August. Management, including CEO Lasse Kristoffersen, is due to present the results.", "kImp": "2분기 실적 발표일(8/11)이 확정되면서, 중동 리스크와 연료비 상승 속 자동차 운반선(PCTC) 시황과 WW의 수익성을 곧 가늠할 수 있게 됐다.", "eImp": "It pins the Q2 2026 earnings date (11 Aug), the next key read on WW's RoRo profitability amid Middle East disruption and higher bunker costs.", "url": "https://www.walleniuswilhelmsen.com/who-we-are/investors/stock-exchange-notices"}]}, {"code": "EE", "type": "news", "kTitle": "Section 6. 에너지 효율·탈탄소", "eTitle": "Section 6. Energy Efficiency", "items": [{"code": "EE", "title": "Efficiency First: Energy Efficiency Takes Centre Stage at SMM 2026", "src": "Maritime Executive", "date": "2026-08-06", "kSum": "함부르크 메세는 9월 1~4일 열리는 SMM 2026에서 200㎡ 규모의 '에너지 효율 허브(Energy Efficiency Hub)'를 신설해 24개 기업이 선박 에너지 효율 솔루션을 전시한다고 밝혔다. 풍력보조추진(WAPS), 태양광, 하이브리드·전동화, 선상 탄소포집(OCCS), 대체연료 시스템, 레트로핏 등 전 밸류체인 기술이 소개된다. BAR Technologies의 WindWings 허브, Cryospain의 극저온 배관, ENOGIA의 폐열회수 ORC 등이 대표 사례로 제시됐다.", "eSum": "Hamburg Messe unveiled a new 200-plus-sq-m Energy Efficiency Hub for SMM 2026 (1-4 September), where 24 companies will showcase efficiency solutions spanning wind-assisted propulsion, solar, hybrid/electrification, onboard carbon capture, alternative-fuel systems and retrofits. Highlighted exhibits include BAR Technologies' WindWings Hub, Cryospain's cryogenic piping and ENOGIA's waste-heat ORC systems. An accompanying Energy Efficiency Stage will debate strategies including nuclear propulsion.", "kImp": "연료 전환 방향이 불확실한 가운데 즉시 실현 가능한 에너지 효율 기술이 탈탄소의 핵심 지렛대로 부상하고 있음을 보여준다.", "eImp": "Signals that immediately deployable efficiency technology is becoming the central near-term decarbonization lever while future-fuel pathways remain unsettled.", "url": "https://maritime-executive.com/corporate/efficiency-first-energy-efficiency-takes-centre-stage-at-smm-2026"}, {"code": "EE", "title": "What's wrong with FuelEU", "src": "Splash247", "date": "2026-08-10", "kSum": "알렉스 뷀랴우체우 선장은 FuelEU Maritime 첫 시행 연도를 평가하며 6가지 문제점을 지적했다. 제21조의 풀링(pooling) 유연성으로 실제 배출 감축 없이도 서류상 준수가 가능해, 준수 실적과 물리적 감축이 혼동된다는 점이 핵심이다. 청정연료 공급 부족, 연료 사용자에게만 부과된 의무, 자금 부족 등도 문제로 꼽았다.", "eSum": "Captain Alex Byelyavtsev identifies six flaws in FuelEU Maritime after its first compliance year, arguing pooling under Article 21 lets ships appear compliant on paper without cutting voyage emissions. He notes clean fuels are not ready at fleet scale, the duty falls only on fuel users rather than producers, and funding for real transition is lacking. The result, he says, is a system that can certify compliance without delivering actual emission reductions.", "kImp": "규제가 공급망보다 앞서가면서 선주들이 실질 감축보다 회계적 준수에 치우칠 수 있다는 구조적 허점을 드러낸다.", "eImp": "Highlights a structural gap in EU decarbonization policy where accounting-based compliance may outpace real emission cuts, shaping owner strategy.", "url": "https://splash247.com/whats-wrong-with-fueleu/"}, {"code": "EE", "title": "INSIGHT: EU ETS Expansion Raises Critical Questions on Fairness and Effectiveness", "src": "Ship & Bunker", "date": "2026-08-10", "kSum": "EmissionLink의 필리포스 이울리아누 대표는 EU가 제안한 해상 EU ETS 확대(2027년 해양설비, 2029년 400~5,000GT 선박 편입)가 공정성과 실효성 측면에서 의문을 남긴다고 지적했다. 향후 IMO 글로벌 탄소가격제와의 이중 부과 위험과, 해운이 부담하는 수익 대비 탈탄소 재투자 부족을 핵심 우려로 꼽았다. 그는 해운 발생 ETS 수익의 최소 50%를 국가 차원의 해양 탈탄소에 재투자해야 한다고 주장했다.", "eSum": "EmissionLink's Philippos Ioulianou argues the European Commission's proposed EU ETS expansion for shipping (offshore from 2027, 400-5,000 GT vessels from 2029) raises fairness and effectiveness concerns. He warns of potential double payment as the IMO moves toward its own carbon price, and of a gap between the revenue shipping contributes and the amount reinvested in decarbonization. He calls for at least 50% of shipping-generated ETS revenue to be reinvested in maritime decarbonization nationally.", "kImp": "EU ETS 확대가 소형·해양지원선까지 확대되며 용선계약과 원가 구조에 직접 영향을 주는 상업적 이슈로 부상함을 보여준다.", "eImp": "Shows the widening EU ETS scope is becoming a core commercial and charter-party issue, not merely a compliance formality, for owners and operators.", "url": "https://shipandbunker.com/news/world/270575-insight-eu-ets-expansion-raises-critical-questions-on-fairness-and-effectiveness"}, {"code": "EE", "title": "Japan Proposes Less Stringent GFI Targets for Shipping", "src": "Ship & Bunker", "date": "2026-08-10", "kSum": "일본은 IMO 넷제로 프레임워크(NZF) 하에서 온실가스 연료집약도(GFI)의 완화된 감축 경로를 제안했다. 기준 목표를 2030년 7%, 2035년 21.9% 감축으로, 직접준수 목표를 2030년 21%에서 2035년 43%로 낮추고, 강제 부담금과 IMO 넷제로기금 삭제도 제안했다. 일본은 2025년 말 상선의 95%가 재래연료선인 점을 들어 선대 교체 속도를 반영한 '달성 가능한' 목표가 필요하다고 강조했다.", "eSum": "Ahead of IMO technical talks in September, Japan submitted revised draft amendments proposing lower GFI reduction factors under the Net-Zero Framework: a 7% base cut in 2030 rising to 21.9% in 2035, and a direct-compliance target of 21% in 2030 to 43% in 2035. It also proposes removing mandatory payments and the IMO Net-Zero Fund. Japan argues targets must reflect fleet-replacement speed, noting 95% of merchant ships were conventional-fuelled at end-2025.", "kImp": "주요 조선국 일본의 완화안은 IMO 글로벌 탄소규제의 최종 강도와 타결 시점에 직접적인 영향을 미친다.", "eImp": "As a major shipbuilding nation's compromise proposal, it directly shapes the ultimate stringency and timing of the IMO's global GHG framework.", "url": "https://shipandbunker.com/news/apac/584026-japan-proposes-less-stringent-gfi-targets-for-shipping"}]}, {"code": "DIG", "type": "news", "kTitle": "Section 7. 디지털라이제이션", "eTitle": "Section 7. Digitalization", "items": [{"code": "DIG", "title": "24,000-TEU ships put smart terminal technology on the shipowner agenda", "src": "The Digital Ship", "date": "2026-08-10", "kSum": "MSC는 24,000 TEU를 넘는 초대형 컨테이너선이 선석·야드·게이트 운영에 더 큰 부담을 주면서 스마트 터미널 기술이 선주 의제로 부상하고 있다고 밝혔다. 대형선 대응을 위해 터미널 디지털화와 자동화 수요가 커지고 있다.", "eSum": "MSC says container ships exceeding 24,000 TEU are placing greater demands on berth, yard and gate operations, pushing smart terminal technology onto the shipowner agenda. The scale of ultra-large vessels is driving demand for terminal digitalisation and automation.", "kImp": "초대형선 확대가 터미널 디지털 인프라 투자를 가속화하는 신호로, 선주와 터미널 간 기술 협력이 중요해진다.", "eImp": "The growth of mega-ships is accelerating investment in digital terminal infrastructure, raising the stakes for owner-terminal tech collaboration.", "url": "https://thedigitalship.com/news/maritime-software/24000-teu-ships-put-smart-terminal-technology-on-the-shipowner-agenda/"}, {"code": "DIG", "title": "BIMCO survey highlights cautious approach to AI-generated contracts", "src": "Smart Maritime Network", "date": "2026-08-06", "kSum": "BIMCO 설문에 따르면 AI가 향후 3~5년 내 해운 계약서 작성에 보편화될 것으로 전망되지만 업계는 아직 신중한 태도를 보이고 있다. 신뢰성과 법적 책임 우려가 도입 속도를 조절하는 요인으로 지적됐다.", "eSum": "A BIMCO survey finds AI is expected to become commonplace in shipping contract drafting within three to five years, but the industry remains cautious. Concerns over reliability and legal accountability are tempering adoption.", "kImp": "해운 상거래의 핵심인 계약 업무에 AI가 진입하는 흐름과 그 속도 조절 요인을 보여준다.", "eImp": "It signals AI's entry into core commercial contracting while flagging the trust barriers that will shape its pace.", "url": "https://smartmaritimenetwork.com/2026/08/06/bimco-survey-highlights-cautious-approach-to-ai-generated-contracts/"}, {"code": "DIG", "title": "Klaipeda Container Terminal to implement berth planning software", "src": "Smart Maritime Network", "date": "2026-08-06", "kSum": "클라이페다 컨테이너 터미널(KCT)이 디지털화 프로그램의 일환으로 Portchain의 Quay 선석 계획 소프트웨어를 도입한다. 선석 배정 최적화를 통해 터미널 운영 효율을 높이려는 목적이다.", "eSum": "Klaipeda Container Terminal (KCT) will implement Portchain's Quay berth planning software as part of its digitalisation programme. The move aims to optimise berth allocation and improve terminal efficiency.", "kImp": "항만 디지털화가 개별 터미널의 선석 계획 자동화로 구체화되는 사례다.", "eImp": "It is a concrete example of port digitalisation reaching individual terminals through automated berth planning.", "url": "https://smartmaritimenetwork.com/2026/08/06/klaipeda-container-terminal-to-implement-berth-planning-software/"}, {"code": "DIG", "title": "PIL expands Intelligence Centre", "src": "Smart Maritime Network", "date": "2026-08-06", "kSum": "퍼시픽 인터내셔널 라인즈(PIL)가 셀로니스(Celonis) 및 카프제미니 산하 WNS와 협력해 글로벌 프로세스 인텔리전스 센터를 확장한다. 프로세스 마이닝과 데이터 분석을 통해 운영 가시성을 높이려는 전략이다.", "eSum": "Pacific International Lines (PIL) has partnered with Celonis and WNS, part of Capgemini, to expand its global Process Intelligence Centre. The initiative leverages process mining and data analytics to boost operational visibility.", "kImp": "선사가 데이터·프로세스 인텔리전스에 투자해 운영 효율을 체계화하는 흐름을 보여준다.", "eImp": "It shows carriers investing in data and process intelligence to systematise operational efficiency.", "url": "https://smartmaritimenetwork.com/2026/08/06/pil-expands-intelligence-centre/"}, {"code": "DIG", "title": "ShipIn raises $52m to expand AI platform", "src": "Smart Maritime Network", "date": "2026-08-04", "kSum": "쉽인(ShipIn)이 상선용 AI 운영 인텔리전스 플랫폼 확장을 위해 5,200만 달러의 신규 투자를 유치했다. 이 플랫폼은 92개 선주사의 1,300척 이상에 도입돼 온보드 카메라·센서·시스템 데이터를 결합해 안전과 생산성을 높인다.", "eSum": "ShipIn has raised US$52 million to expand its AI-powered operational intelligence platform for commercial shipping. Deployed by 92 shipowners across more than 1,300 vessels, it combines onboard camera, sensor and system data to improve safety and productivity.", "kImp": "대규모 투자 유치는 온보드 AI 시각·데이터 분석 시장의 성장성을 방증한다.", "eImp": "The sizeable raise underscores the growth potential of onboard AI vision and data analytics.", "url": "https://smartmaritimenetwork.com/2026/08/04/shipin-raises-52m-to-expand-ai-platform/"}, {"code": "DIG", "title": "Sedna integrates with PortPal for AI port agency", "src": "Smart Maritime Network", "date": "2026-08-04", "kSum": "세드나(Sedna)가 PortPal과 협력해 이메일 플랫폼에 포트콜 관리 기능을 통합했다. 항만 대리점이 운영 이메일을 구조화된 데이터로 전환해 업무를 자동화할 수 있게 한다.", "eSum": "Sedna has partnered with PortPal to integrate port call management into its email platform. The integration lets port agencies convert operational email into structured data to automate workflows.", "kImp": "AI 기반 이메일·포트콜 자동화가 항만 대리점 업무의 디지털 전환을 가속한다.", "eImp": "AI-driven email and port-call automation is accelerating digital transformation of port agency work.", "url": "https://smartmaritimenetwork.com/2026/08/04/sedna-integrates-with-portpal-for-ai-port-agency/"}, {"code": "DIG", "title": "ZeroNorth launches agentic AI for voyage optimisation", "src": "Smart Maritime Network", "date": "2026-08-04", "kSum": "제로노스(ZeroNorth)가 항해·선박·연료 관리 워크플로 전반의 운영 업무를 자동화하는 에이전틱 AI 애플리케이션 'Propel'을 출시했다. 실험 단계를 넘어 실무 자동화로 AI 활용을 확장하는 사례다.", "eSum": "ZeroNorth has introduced Propel, an agentic AI application to automate operational tasks across voyage, vessel and fuel management workflows. It marks a shift from experimentation toward operational AI automation.", "kImp": "에이전틱 AI가 항해 최적화 실무에 적용되며 자율적 의사결정 지원 시대를 앞당긴다.", "eImp": "Agentic AI moving into voyage optimisation brings autonomous decision-support closer to daily operations.", "url": "https://smartmaritimenetwork.com/2026/08/04/zeronorth-launches-agentic-ai-for-voyage-optimisation/"}, {"code": "DIG", "title": "Samsung Heavy and Mousterian in floating data centre deal", "src": "Smart Maritime Network", "date": "2026-08-04", "kSum": "삼성중공업(SHI)과 미국 개발사 무스테리안(Mousterian)이 부유식 데이터센터 최초 배치를 위한 엔지니어링 계약을 체결했다. 해상 AI·데이터 인프라라는 신흥 시장을 겨냥한 움직임이다.", "eSum": "Samsung Heavy Industries (SHI) and US developer Mousterian Corporation have signed an engineering contract for the first deployment of a floating data centre. The deal targets the emerging market for offshore AI and data infrastructure.", "kImp": "해상 부유식 데이터센터는 조선과 디지털 인프라가 교차하는 새로운 사업 기회를 연다.", "eImp": "Floating data centres open a new business frontier where shipbuilding meets digital infrastructure.", "url": "https://smartmaritimenetwork.com/2026/08/04/samsung-heavy-and-mousterian-in-floating-data-centre-deal/"}]}, {"code": "TECH", "type": "news", "kTitle": "Section 8. 선박관리 기술", "eTitle": "Section 8. Ship Manager Technical", "items": [{"code": "TECH", "title": "Hamworthy Returns with Renewed Focus on the Future of Marine Water & Waste", "src": "marinelink", "date": "2026-08-10", "kSum": "뷔르실라(Wärtsilä)의 물·폐기물 사업부가 Solix Group에 매각되며 독립기업으로 재출범한 햄워시(Hamworthy)의 CEO 프레이저 스콧(Fraser Scott)이 선박 환경설비의 위상 변화를 짚었다. 폐수·오수·빌지수 처리, 청수 생산, 밸러스트수 관리, 고형폐기물 처리 등 신조·개조용 통합 시스템이 이제는 '설치 후 방치'가 아니라 운항 내내 매일 규정 준수를 입증해야 하는 핵심 인프라가 됐다는 점을 강조했다. 특히 승선인원 감소와 규제 강화 속에서 자기충족형·자기조절형 생물학적 처리 시스템의 안정성과 수명주기 성능이 중요해졌다고 봤다.", "eSum": "In an opinion piece, Hamworthy CEO Fraser Scott reflects on the company's relaunch as an independent marine water and waste specialist (after Wärtsilä's Water & Waste division was divested to Solix Group) and how environmental systems have shifted from check-box auxiliaries to essential shipboard infrastructure. He argues that tightening MARPOL Annex IV/V and regional rules, leaner crews and daily compliance demands make lifecycle performance, reliability and self-regulating biological treatment more critical than ever. Dry-waste management, sludge handling and system integration are flagged as the most active development areas.", "kImp": "선박관리 기술팀 입장에서 밸러스트수·오폐수·고형폐기물 설비의 수명주기 안정성과 상시 규정 준수 리스크를 재점검하게 하는 실무적 시사점을 제공한다.", "eImp": "Prompts ship-manager technical teams to reassess lifecycle reliability and continuous-compliance risk of ballast, sewage/grey-water and solid-waste systems as crews shrink and inspections intensify.", "url": "https://www.marinelink.com/news/hamworthy-returns-renewed-focus-future-541936"}]}, {"code": "HR", "type": "news", "kTitle": "Section 9. 해기인력·선원", "eTitle": "Section 9. Marine HR", "items": [{"code": "HR", "title": "Seafarer happiness falls as \"acute shock\" hardens into \"chronic strain\"", "src": "missiontoseafarers", "date": "2026-08-03", "kSum": "국제해원선교회(The Mission to Seafarers)가 발표한 2026년 2분기 선원행복지수(Seafarers Happiness Index)가 1분기 7.18에서 6.87/10로 하락했다. 페르시아만 분쟁의 급성 충격이 만성적 피로로 굳어지면서, 제한된 상륙휴가(상륙 점수 5.72로 최저), 과중한 업무, 실질임금 정체가 사기를 갉아먹고 있다. 여성 응답자(6.06)와 중동·컨테이너선 근무 선원, 35~55세 중견 선원의 사기가 특히 낮았다.", "eSum": "The Mission to Seafarers' Q2 2026 Seafarers Happiness Index fell to 6.87/10 from 7.18 in Q1, marking a shift 'from acute shock to chronic strain.' Limited shore leave (lowest score at 5.72), heavy workloads and stagnant real wages are steadily eroding morale. Female respondents (6.06), Middle East and container-ship crews, and mid-career seafarers aged 35-55 reported the weakest scores.", "kImp": "선원 사기 저하와 상륙휴가·휴식·연결성 문제는 채용·유지 전략과 직결되므로 마린HR팀이 복지 투자 우선순위를 재점검하는 근거가 된다.", "eImp": "Declining morale and shore-leave/rest/connectivity gaps feed directly into recruitment and retention, giving a marine HR team concrete grounds to reprioritise welfare investment.", "url": "https://www.missiontoseafarers.org/news/seafarer-happiness-falls-as-acute-shock-hardens-into-chronic-strain"}, {"code": "HR", "title": "Flag states pressed to ditch paper training books", "src": "splash247", "date": "2026-08-06", "kSum": "해사 교육기업 마린팔스(MarinePALS)가 아직 종이 훈련기록부에 의존하는 기국(flag administration)들에 전자식 대안 승인 경로를 마련하라고 촉구했다. 영국은 상선훈련위원회(MNTB)가 개발한 클라우드 기반 전자훈련기록부를 도입 중이며, 필리핀·인도도 디지털 생도 기록 시스템을 구축하고 있다. 규제 접근이 제각각이어서 생도·선박관리사·교육기관이 종이와 디지털 사이에서 분열돼 있다고 지적했다.", "eSum": "Training provider MarinePALS has urged flag administrations still reliant on paper training record books to create approval routes for electronic alternatives. The UK is rolling out a cloud-based electronic training record book from the Merchant Navy Training Board, while the Philippines and India are building digital cadet-record systems. The uneven regulatory approach leaves cadets, shipmanagers and training institutions split between paper and digital systems.", "kImp": "생도 훈련기록의 디지털화는 자격 검증·해기사 양성 파이프라인 효율과 직결되므로, 채용·교육 담당 HR팀이 기국별 승인 현황을 파악해 둘 필요가 있다.", "eImp": "Digitising cadet training records bears directly on competency verification and the officer-training pipeline, so HR teams handling recruitment and training should track which flags accept e-record books.", "url": "https://splash247.com/flag-states-pressed-to-ditch-paper-training-books/"}]}, {"code": "HSEQ", "type": "news", "kTitle": "Section 10. HSEQ·손해방지", "eTitle": "Section 10. HSEQ", "items": [{"code": "HSEQ", "title": "MSF: Complacency during tubular cargo operations", "src": "safety4sea", "date": "2026-08-10", "kSum": "해양안전포럼(Marine Safety Forum, MSF)이 갑판 하역 작업 중 발생한 부상 사고의 교훈을 공유했다. 13인치 케이싱 파이프 번들을 갑판에 내려놓은 뒤 슬링을 분리하던 중 파이프 다발이 굴러 작업자가 왼쪽 발목을 다쳤다. MSF는 반복 작업에서의 안일함(complacency)이 근본 원인이라고 지적했다.", "eSum": "The Marine Safety Forum (MSF) shared lessons from an incident in which a crew member injured his left ankle when a bundle of 13-inch casing pipes rolled during sling disconnection after being landed on deck. MSF flagged complacency in routine tubular cargo handling as a key contributing factor.", "kImp": "관·파이프 등 구름 위험이 있는 화물 하역 시 슬링 해제 단계의 위치 선정과 화물 고박 관리가 부상 예방의 핵심임을 상기시킨다.", "eImp": "A reminder that positioning during sling release and securing of rolling cargo (pipes/tubulars) is critical to preventing crew injuries during deck operations.", "url": "https://safety4sea.com/msf-complacency-during-tubular-cargo-operations/"}, {"code": "HSEQ", "title": "Sanctioned tanker sinks further off Oman as oil spill spreads", "src": "safety4sea", "date": "2026-08-10", "kSum": "약 100만 배럴의 원유를 실은 제재 대상 유조선이 오만(Oman) 앞바다에서 수 주간 좌초된 채 더 가라앉으면서 위성 영상상 기름 유출이 빠르게 확산되고 있다. 유출 지역은 보호 해양구역 인근으로 환경 피해가 우려된다.", "eSum": "A sanctioned tanker carrying nearly 1 million barrels of crude oil is sinking further after weeks aground off Oman, with satellite imagery showing a rapidly expanding oil spill near a protected marine area. The situation raises serious pollution and environmental-response concerns.", "kImp": "그림자 선단(shadow fleet)과 방치 좌초선이 대형 유류오염으로 이어질 수 있음을 보여주며, 오염 대응·보험·연안국 관할 리스크 관리의 중요성을 부각한다.", "eImp": "Highlights how shadow-fleet and abandoned casualties can escalate into major pollution events, underscoring spill-response readiness and coastal-state/insurance risk management.", "url": "https://safety4sea.com/sanctioned-tanker-sinks-further-off-oman-as-oil-spill-spreads/"}, {"code": "HSEQ", "title": "Lessons learned: Safety-critical systems must be designed to withstand failure", "src": "safety4sea", "date": "2026-08-06", "kSum": "CHIRP Maritime가 조난 선박에 대응하던 구조선(rescue vessel)이 혼잡한 통항 해역에서 조종제한(RAM) 등화를 표시한 직후 전기 화재가 발생한 사고의 교훈을 공유했다. 안전에 핵심적인 시스템은 단일 고장에도 견딜 수 있도록 설계·이중화되어야 한다는 점이 강조됐다.", "eSum": "CHIRP Maritime drew lessons from an incident where a rescue vessel responding to a disabled ship suffered an electrical fire shortly after displaying RAM lights in a busy traffic area. The report stresses that safety-critical systems must be designed with redundancy to withstand single-point failures.", "kImp": "구조·비상 대응 상황에서 전기계통 고장이 2차 사고로 번질 수 있으므로, 핵심 계통의 이중화와 고장 대비 설계·점검이 필요함을 시사한다.", "eImp": "Shows how an electrical fault can compound into a secondary casualty during emergency response, reinforcing the need for redundancy and fault-tolerant design/maintenance of critical systems.", "url": "https://safety4sea.com/lessons-learned-safety-critical-systems-must-be-designed-to-withstand-failure/"}, {"code": "HSEQ", "title": "Lessons learned: In polar waters, safe navigation requires multiple sources", "src": "safety4sea", "date": "2026-08-05", "kSum": "CHIRP Maritime가 극지 해역을 항해하던 선박에서 선교자원관리(BRM) 실패가 발생한 사고의 교훈을 공유했다. 극지 항해에서는 단일 정보원에 의존하지 말고 다중 정보원을 교차 확인해야 안전이 확보된다는 점을 강조했다.", "eSum": "CHIRP Maritime drew lessons from an incident where a vessel in polar waters experienced a bridge resource management (BRM) failure. It stresses that safe polar navigation requires cross-checking multiple information sources rather than relying on a single one.", "kImp": "해도 신뢰도가 낮은 극지·원거리 해역에서 다중 정보원 확인과 견고한 BRM이 좌초·충돌 예방에 필수임을 상기시킨다.", "eImp": "A reminder that in poorly charted polar/remote areas, multi-source verification and robust BRM are essential to prevent grounding or collision.", "url": "https://safety4sea.com/lessons-learned-in-polar-waters-safe-navigation-requires-multiple-sources/"}, {"code": "HSEQ", "title": "Lessons learned: Pilots are human and can make mistakes", "src": "safety4sea", "date": "2026-08-04", "kSum": "선장회(The Nautical Institute)가 도선사(pilot)의 판단 착오가 관련된 사고의 교훈을 공유했다. 도선사도 인간이므로 실수할 수 있으며, 선교팀은 도선 중에도 감시와 상호 확인을 유지해야 한다는 점을 강조했다.", "eSum": "The Nautical Institute drew lessons from an incident involving a pilot's error, emphasizing that pilots are human and can make mistakes. The bridge team must maintain independent monitoring and cross-checking even while under pilotage.", "kImp": "도선사 승선 중에도 선장·선교팀의 독립적 감시와 이의 제기(challenge) 문화가 유지되어야 도선 관련 사고를 막을 수 있음을 시사한다.", "eImp": "Underlines that master/bridge-team oversight of the pilot's actions and clear challenge-and-response practice remain essential to avoid pilotage-related casualties.", "url": "https://safety4sea.com/lessons-learned-pilots-are-human-and-can-make-mistakes/"}, {"code": "HSEQ", "title": "Lessons learned: An unusual condition is a safety signal that requires attention", "src": "safety4sea", "date": "2026-08-04", "kSum": "CHIRP Maritime가 약화된 안전 장벽과 미흡한 정비가 기관실 화재 직전 상황으로 이어진 사고의 교훈을 공유했다. 부임한 선장이 소방·구명 장비가 기한 만료·불완전·사용 불가 상태임을 발견했고, 시정 후에야 수년 만에 처음으로 소방·퇴선 훈련이 실시됐다. 비정상적인 냄새·소리·상태는 원인이 규명될 때까지 반드시 주의해야 할 안전 신호임을 강조했다.", "eSum": "CHIRP Maritime drew lessons from a case where weakened safety barriers and incomplete maintenance nearly caused an engine-room fire. A relieving master found firefighting and lifesaving equipment out of date, incomplete or unserviceable; only after rectification were fire and abandon-ship drills held for the first time in years. An unusual smell, sound or condition is a safety signal that must be investigated until understood.", "kImp": "정비 이월과 형식적 안전관리가 중대 사고로 이어질 수 있으며, 이상 징후를 조기에 조사하는 문화와 승선 인수인계 시 철저한 안전 점검이 중요함을 보여준다.", "eImp": "Demonstrates how deferred maintenance and paper-only safety management can lead to serious incidents, and the value of investigating anomalies early and conducting thorough handover safety checks.", "url": "https://safety4sea.com/lessons-learned-an-condition-is-a-safety-signal-that-requires-attention/"}]}, {"code": "KR", "type": "news", "kTitle": "Section 11. 한국 해운시장", "eTitle": "Section 11. Korean Shipping Market", "items": [{"code": "KR", "title": "‘탱크선 약진’ 팬오션 2분기 영업익 1937억…57%↑", "src": "코리아쉬핑가제트(ksg.co.kr)", "date": "2026-08-10", "kSum": "팬오션(Pan Ocean)이 2026년 2분기 영업이익 1937억원, 순이익 1375억원, 매출 1조9137억원을 기록해 전년 동기 대비 영업익 57%·매출 48% 급증했다. 호르무즈 사태와 호주 수입 수요로 탱크선 영업익이 166% 늘어난 437억원을 기록했고, 벌크선도 벌크운임지수(BDI) 강세로 60% 증가했다. SK해운 초대형 유조선(VLCC) 10척 인수와 신조 7척 발주 등으로 VLCC 선대를 21척으로 확장 중이며, 상반기 누적 영업익은 3346억원(42%↑)에 달했다.", "eSum": "Pan Ocean posted Q2 operating profit of KRW193.7bn (+57% YoY) on revenue of KRW1.91tn (+48%). Its tanker unit surged 166% on Hormuz-driven and Australian import demand, while bulk rose 60% on a strong BDI. It is expanding its VLCC fleet to 21 ships via SK Shipping purchases and newbuild orders; first-half operating profit reached KRW334.6bn (+42%).", "kImp": "국적 대형선사의 실적 호조와 대규모 VLCC 투자는 중동 지정학 리스크가 한국 해운 수익성에 미치는 영향을 뚜렷이 보여준다.", "eImp": "Shows how Middle East geopolitics is lifting Korean shipping earnings and driving major tanker-fleet investment.", "url": "https://www.ksg.co.kr/news/main_newsView.jsp?pNum=147760"}, {"code": "KR", "title": "2028년 제4차 유엔해양총회 개최도시로 부산 선정", "src": "쉬핑뉴스넷(shippingnewsnet.com)", "date": "2026-08-10", "kSum": "해양수산부(장관 황종우)가 2028년 우리나라에서 열리는 제4차 유엔해양총회(UN Ocean Conference)의 개최도시로 부산광역시를 선정했다. 제주특별자치도와 경합 끝에 해양산업·연구·교육 기반 집적과 총회 취지와의 연계성을 높이 평가받았다. UN 회원국 등 약 2만 명이 참석하는 해양분야 최대 국제회의로, 연말 유엔총회 이행방식 결의안에 반영될 예정이다.", "eSum": "Korea's Ministry of Oceans and Fisheries selected Busan to host the 4th UN Ocean Conference in 2028, beating Jeju on its concentration of marine industry, research and education. The event—the largest high-level ocean meeting with ~20,000 attendees—will be reflected in a year-end UN modalities resolution.", "kImp": "부산이 글로벌 해양 도시로서 위상을 강화하고 국내 해양산업을 세계에 알릴 기회를 확보했다.", "eImp": "Bolsters Busan's status as a global maritime hub and showcases Korea's ocean industry worldwide.", "url": "http://www.shippingnewsnet.com/news/articleView.html?idxno=71540"}, {"code": "KR", "title": "해수부, 연안선박 현대화 펀드 2차 대상 3개 선사 선정", "src": "쉬핑뉴스넷(shippingnewsnet.com)", "date": "2026-08-10", "kSum": "해양수산부가 2026년 제2차 ‘연안선박 현대화 펀드’ 사업대상자로 세양쉬핑·태경탱커·독도크루즈 3개 연안선사를 선정했다. 2016년부터 총 2490억원 규모로 14척을 지원했으며, 이번 선사는 선가의 50%를 펀드로 지원받아 15년간 상환 후 선박을 취득한다. 세양쉬핑과 태경탱커는 공동 발주로 건조비를 절감하며, 해수부는 8~9월 중 3차 공모를 진행할 계획이다.", "eSum": "Korea's MOF selected three coastal operators (Seyang Shipping, Taekyung Tanker, Dokdo Cruise) for the 2nd 2026 Coastal Vessel Modernization Fund. The KRW249bn fund has backed 14 ships; new recipients get 50% of the ship price funded, repaid over 15 years, with a 3rd call due in Aug–Sept.", "kImp": "노후 연안선박 교체 지원은 섬 주민 해상교통권, 연안물류 경쟁력, 친환경 전환과 직결된다.", "eImp": "Supports replacing aging coastal ships—key to island transport access, coastal-logistics competitiveness and green transition.", "url": "http://www.shippingnewsnet.com/news/articleView.html?idxno=71535"}, {"code": "KR", "title": "KOBC 컨운임종합지수(KCCI) 4288달러…전주比 3.6% 상승", "src": "쉬핑뉴스넷(shippingnewsnet.com)", "date": "2026-08-10", "kSum": "한국해양진흥공사(KOBC)의 컨테이너운임종합지수(KCCI)가 8월10일 기준 4288달러로 전주 대비 150달러(3.6%) 올랐다. 최근 컨테이너 해상운임의 반등 흐름을 보여주는 지표다.", "eSum": "KOBC's container freight composite index (KCCI) rose to $4,288 as of Aug 10, up $150 (3.6%) week-on-week, signaling a rebound in container freight rates.", "kImp": "국적 화주·선사 수익성과 직결되는 핵심 운임 지표의 방향성을 가늠할 수 있다.", "eImp": "A key freight benchmark directly tied to Korean shippers' and carriers' profitability.", "url": "http://www.shippingnewsnet.com/news/articleView.html?idxno=71539"}, {"code": "KR", "title": "‘북극항로 활용 촉진·연관산업 육성 특별법’ 시행령 제정안 입법예고", "src": "쉬핑뉴스넷(shippingnewsnet.com)", "date": "2026-08-10", "kSum": "해양수산부가 ‘북극항로 활용 촉진 및 연관산업 육성에 관한 특별법’ 시행령 제정령안을 입법예고했다. 북극항로 개척과 관련 산업 육성을 위한 제도적 기반을 마련하는 조치다.", "eSum": "Korea's MOF issued for public comment the enforcement decree of the special act on promoting Arctic route use and fostering related industries, laying the institutional groundwork for Arctic shipping development.", "kImp": "북극항로는 한국 해운·조선의 미래 성장축으로, 정책 제도화가 본격화되고 있다.", "eImp": "The Arctic route is a future growth axis for Korean shipping and shipbuilding; policy is now being institutionalized.", "url": "http://www.shippingnewsnet.com/news/articleView.html?idxno=71536"}, {"code": "KR", "title": "부산 해양수산 공공기관, 공공데이터 활용 활성화 캠페인", "src": "코리아쉬핑가제트(ksg.co.kr)", "date": "2026-08-10", "kSum": "부산항만공사(BPA)와 한국해양진흥공사(KOBC), 한국해양수산개발원(KMI), 한국해양수산연수원, 국립해양박물관이 부산지역 해양수산 공공데이터 이용 활성화에 나섰다. BPA는 지난 6일 국립해양박물관에서 관계기관과 함께 데이터 개방·활용 확대 방안을 논의했다.", "eSum": "Busan Port Authority (BPA), KOBC, KMI, the Korea Institute of Maritime & Fisheries Technology and the National Maritime Museum launched a campaign to boost use of Busan's maritime public data, meeting on Aug 6 at the museum.", "kImp": "부산항 중심의 해양수산 데이터 개방은 항만·물류 디지털 혁신의 기반이 된다.", "eImp": "Opening Busan-centered maritime data underpins digital innovation in ports and logistics.", "url": "https://www.ksg.co.kr/news/main_newsView.jsp?pNum=147804"}]}, {"code": "INS", "type": "news", "kTitle": "Section 12. 해상보험 (H&M)", "eTitle": "Section 12. Marine Insurance (H&M)", "items": [{"code": "INS", "title": "이란, 호르무즈 해협서 유조선 2척 공격 주장", "src": "Insurance Marine News (insurancemarinenews.com)", "date": "2026-08-10", "kSum": "이란이 8월8일 새벽 호르무즈 해협에서 ‘적대적’ 표적 2척을 타격했다고 주장했다(미확인). 표적은 원유운반선 니소스 케아(Nissos Kea) 등으로 추정된다. 중동 긴장 고조로 선체·전쟁위험(H&M·War Risk) 보험료 인상 압력이 커지고 있다.", "eSum": "Iran claimed (unconfirmed) it struck two \"hostile\" targets—thought to be crude tankers including Nissos Kea—in the Strait of Hormuz early on Aug 8, adding pressure to hull and war-risk premiums amid rising Middle East tensions.", "kImp": "호르무즈 전쟁위험 급등은 유조선 선주·화주의 보험비용과 항로 선택에 직접 영향을 준다.", "eImp": "Escalating Hormuz war risk directly affects tanker owners'/shippers' insurance costs and routing.", "url": "https://insurancemarinenews.com/insurance-marine-news/iran-claims-strikes-on-two-vessels/"}, {"code": "INS", "title": "흑해서 독일 소유 벌크선, 드론 공격 피해", "src": "Insurance Marine News (insurancemarinenews.com)", "date": "2026-08-10", "kSum": "러시아-우크라이나 전쟁의 국제화와 흑해의 전쟁지역화가 지속되는 가운데 독일 선사 소유 벌크선이 드론 공격을 받았다. 흑해 항로의 선체·적하(Cargo) 전쟁위험이 다시 부각되고 있다.", "eSum": "A German-owned bulk carrier was hit by drones in the Black Sea as the Russia-Ukraine war internationalizes and the Black Sea re-emerges as a war zone, spotlighting hull and cargo war risk on the route.", "kImp": "흑해 곡물·벌크 항로의 전쟁위험 확대는 적하보험과 운임에 파급된다.", "eImp": "Widening Black Sea war risk ripples into cargo insurance and freight.", "url": "https://insurancemarinenews.com/cargo/german-owned-bulk-carrier-attacked-by-drones-in-the-black-sea/"}, {"code": "INS", "title": "손보재팬, 업계 첫 GPS 재밍 손실 보상 보험 출시", "src": "Insurance Marine News (insurancemarinenews.com)", "date": "2026-08-10", "kSum": "일본 손보재팬(Sompo Japan)이 선박 항법장치에 대한 전파 교란(GPS 재밍)으로 인한 경제적 손실을 보상하는 업계 최초의 보험을 출시했다. 지정학적 전자전 위험을 겨냥한 신상품이다.", "eSum": "Sompo Japan launched what it calls the shipping industry's first insurance specifically covering economic losses from radio interference (GPS jamming) with ship navigation, targeting geopolitical electronic-warfare risk.", "kImp": "GPS 재밍 등 신종 위험에 대한 보험 공백을 메우는 상품의 등장이라는 점에서 주목된다.", "eImp": "A notable product filling coverage gaps for emerging risks such as GPS jamming.", "url": "https://insurancemarinenews.com/insurance-marine-news/sompo-moves-to-close-gps-jamming-insurance-gap/"}, {"code": "INS", "title": "리졸브 마린, MSC 발틱 III 좌초선 인양 다음 단계 진행", "src": "Insurance Marine News (insurancemarinenews.com)", "date": "2026-08-10", "kSum": "캐나다 뉴펀들랜드 해안에서 리졸브 마린(Resolve Marine)이 좌초한 MSC 발틱 III(MSC Baltic III) 잔해를 300t급 체인 풀러 12기를 설치해 서서히 이동시키는 인양 작업을 진행 중이다. 대형 좌초 사고의 구난·선체보험 이슈가 이어지고 있다.", "eSum": "Off Newfoundland, Resolve Marine is advancing salvage of the grounded MSC Baltic III, installing 12 300-tonne chain pullers to slowly move the wreck—a major grounding raising salvage and hull insurance issues.", "kImp": "대형 좌초선 인양 비용은 선체보험과 구난 시장의 핵심 리스크로 작용한다.", "eImp": "Major wreck salvage costs are a core risk for the hull and salvage markets.", "url": "https://insurancemarinenews.com/insurance-marine-news/resolve-marine-is-completing-next-stage-of-msc-baltic-iii-salvage/"}, {"code": "INS", "title": "태풍 돌핀, 오키나와 강타…中 항만·페리 운항 중단", "src": "Insurance Marine News (insurancemarinenews.com)", "date": "2026-08-10", "kSum": "태풍 돌핀(Dolphin)이 8월8일 일본 오키나와를 강타해 5명이 부상하고 1만4000여 건물이 정전됐다. 중국도 상륙에 대비해 항만과 페리 항로를 폐쇄했다. 화물 지연·손상 등 적하보험 관련 리스크가 확대되고 있다.", "eSum": "Typhoon Dolphin struck Okinawa on Aug 8, injuring five and cutting power to 14,000 buildings, while China shut ports and ferry routes ahead of landfall—raising cargo delay/damage insurance exposure.", "kImp": "기상 재해는 아시아 항만 운영과 적하보험 손해율에 직접 영향을 준다.", "eImp": "Weather catastrophes directly affect Asian port operations and cargo insurance loss ratios.", "url": "https://insurancemarinenews.com/cargo/typhoon-dolphin-hits-okinawa-china-shuts-ports-ahead-of-landfall/"}, {"code": "INS", "title": "영국, 추가 제재로 선박 6척 지정…대러 해운 압박 확대", "src": "Insurance Marine News (insurancemarinenews.com)", "date": "2026-08-10", "kSum": "영국이 러시아 에너지를 운송한 선박 6척을 포함한 신규 대러 제재 패키지를 발표하며 해운·금융·산업 부문을 겨냥했다. 제재 대상 확대로 선체·전쟁위험·적하보험 인수 심사와 컴플라이언스 부담이 커지고 있다.", "eSum": "The UK unveiled a new sanctions package targeting shipping, banking and industry, adding six vessels it said transported Russian energy—raising hull/war/cargo underwriting and compliance burdens.", "kImp": "제재 확대는 해상보험 인수 심사와 P&I 컴플라이언스 전반에 파급된다.", "eImp": "Expanding sanctions ripple across marine insurance underwriting and compliance.", "url": "https://insurancemarinenews.com/insurance-marine-news/latest-sanctions-package-from-uk-adds-six-more-vessels/"}, {"code": "INS", "title": "라인강 수위 급락, 독일 경제·내륙 수운 위협", "src": "Insurance Marine News (insurancemarinenews.com)", "date": "2026-08-10", "kSum": "라인강 수위가 기록적으로 낮아지면서 독일 경제와 내륙 수운이 위협받고 있다고 독일 교통장관이 밝혔다. 바지선 감재(減載) 운항으로 물류·적하 리스크가 확대되고 있다.", "eSum": "Record-low Rhine water levels are threatening the German economy and inland waterway transport, Germany's transport minister said, as reduced barge loads heighten logistics and cargo risk.", "kImp": "내륙 수운 차질은 유럽 화물 흐름과 적하보험에 영향을 미친다.", "eImp": "Inland waterway disruption affects European cargo flows and cargo insurance.", "url": "https://insurancemarinenews.com/keep/low-water-levels-on-rhine-threaten-german-economy/"}, {"code": "INS", "title": "정박 중인 이란 유조선 급증…美 봉쇄 효과 가시화", "src": "Insurance Marine News (insurancemarinenews.com)", "date": "2026-08-10", "kSum": "미국의 대이란 봉쇄로 다수의 이란산 원유 유조선이 운항하지 못하고 정박 중인 것으로 나타나 제재·봉쇄가 효과를 내고 있다는 분석이 나왔다. 미국은 물류·정치적 부담 속에 평화협정을 모색하고 있다.", "eSum": "Dozens of Iranian oil tankers are idling, showing the US blockade is working, even as Washington seeks a peace deal amid logistical strains and domestic political pressure ahead of the mid-terms.", "kImp": "이란 유조선 정체는 원유 물동량, 탱커 시장, 제재 관련 보험 리스크에 영향을 준다.", "eImp": "Idling Iranian tankers affect crude flows, the tanker market and sanctions-related insurance risk.", "url": "https://insurancemarinenews.com/insurance-marine-news/dozens-of-idling-iranian-oil-tankers-show-us-blockade-is-working/"}]}, {"code": "PNI", "type": "news", "kTitle": "Section 13. P&I 클럽", "eTitle": "Section 13. P&I Clubs", "items": [{"code": "PNI", "title": "국제그룹 P&I 클럽, 전쟁위험 클래스 추가보험료(AP) 지역 개정 공지", "src": "Insurance Marine News (insurancemarinenews.com)", "date": "2026-08-03", "kSum": "노스스탠다드(NorthStandard)·스웨디시 클럽(The Swedish Club)·스팀십(Steamship)의 전쟁위험(War Risks) 클래스가 추가보험료(Additional Premium, AP) 부과 지역을 개정해 공지했으며, 각기 다른 시점에 발효될 예정이다. 변화하는 지정학 리스크에 맞춰 전쟁위험 담보를 조정하는 조치다.", "eSum": "The War Risks classes of NorthStandard, The Swedish Club and Steamship published revised additional-premium (AP) areas, effective on various dates—adjusting war-risk cover in line with shifting geopolitical risk.", "kImp": "AP 지역 개정은 선주의 전쟁위험 담보 비용과 항로 리스크 산정에 직접 영향을 준다.", "eImp": "Revised AP areas directly affect owners' war-risk costs and route risk assessment.", "url": "https://insurancemarinenews.com/marine-liability/"}]}, {"code": "VET", "type": "news", "kTitle": "Section 14. 베팅·검사", "eTitle": "Section 14. Vetting & Inspection", "items": [{"code": "VET", "title": "최근 7일간 신규 소식이 확인되지 않았습니다", "src": "—", "date": "2026-08-10", "kSum": "이 기간 해당 분야의 신선한 기사가 확인되지 않았습니다. 다음 갱신 시 보완됩니다.", "eSum": "No fresh items were confirmed in this category over the last 7 days; it will be updated in the next cycle.", "kImp": "-", "eImp": "-", "url": "https://brightatsea-alt.github.io/maritime-daily-digest/"}]}, {"code": "CLASS", "type": "news", "kTitle": "Section 15. 선급", "eTitle": "Section 15. Classification Societies", "items": [{"code": "CLASS", "title": "ABS and Samsung Heavy Industries advance floating data centre", "src": "Container News", "date": "2026-08-05", "kSum": "ABS(미국선급, American Bureau of Shipping)와 삼성중공업(Samsung Heavy Industries)이 한미 조선 파트너십 하에 부유식 데이터센터 관련 두 건의 이정표를 발표했다. 50MW급 부유식 데이터센터 설계에 대한 설계승인(Design Approval) 계약과 200MW급 개념설계에 대한 기본승인(AiP)을 획득했다.", "eSum": "ABS and Samsung Heavy Industries (SHI) announced two floating data centre milestones under the Korea-US Shipbuilding Partnership: a design approval agreement for SHI's 50 MW design and a new Approval in Principle (AiP) for its 200 MW concept.", "kImp": "부유식 데이터센터는 해양 자산의 새로운 성장 분야이며, 선급의 설계승인과 AiP는 상용화로 가는 핵심 관문이다. 한미 조선협력이라는 맥락에서 전략적 의미가 크다.", "eImp": "Floating data centres are an emerging offshore asset class; class design approval and AiP are key gateways to commercialisation, carrying strategic weight within Korea-US shipbuilding cooperation.", "url": "https://container-news.com/abs-and-samsung-heavy-industries-advance-floating-data-centre/"}, {"code": "CLASS", "title": "KR certifies 3D printing technology, expanding applications from new part production to maintenance and repair", "src": "Korean Register (KR)", "date": "2026-08-10", "kSum": "한국선급(KR, Korean Register)이 적층제조(3D 프린팅) 기술을 인증하고, 신규 부품 생산에서 방산·조선 분야의 정비·수리(MRO)까지 승인 적용 범위를 확대했다고 밝혔다.", "eSum": "Korean Register (KR) announced certification of additive manufacturing (3D printing) technology, broadening approved applications from new-part production to maintenance and repair across the defense and shipbuilding sectors.", "kImp": "3D 프린팅 부품의 선급 인증은 예비품 조달 리드타임을 줄이고 공급망 유연성을 높인다. MRO로의 확대는 실질적 운항비 절감으로 이어진다.", "eImp": "Class certification of 3D-printed parts shortens spares lead times and adds supply-chain flexibility; extension into MRO translates into real operating-cost savings.", "url": "https://www.krs.co.kr/eng/"}, {"code": "CLASS", "title": "ClassNK releases TEC-1379 on Tokyo/Paris MoU joint CIC on cargo securing", "src": "ClassNK", "date": "2026-08-07", "kSum": "일본선급(ClassNK)이 기술정보 TEC-1379를 발행해, 2026년 9월 1일 시작되는 도쿄·파리 MOU 합동 집중점검(CIC, 화물 고박) 대상과 준비 사항을 선주·운항자에게 안내했다.", "eSum": "ClassNK issued Technical Information TEC-1379 informing owners and operators of the upcoming Tokyo/Paris MoU joint Concentrated Inspection Campaign (CIC) on cargo securing and preparatory measures.", "kImp": "9월 CIC를 앞두고 선급의 사전 안내는 출항정지 리스크를 낮추는 실무 지침이 된다.", "eImp": "Ahead of the September CIC, class guidance provides practical direction to reduce detention risk.", "url": "https://www.classnk.or.jp/hp/en/index.html"}, {"code": "CLASS", "title": "DNV: Port State Control CIC 2026 official questionnaire now published", "src": "DNV", "date": "2026-08-04", "kSum": "DNV가 파리·도쿄 MOU 합동 CIC(화물 고박)가 2026년 9월 1일 시작되며, 공식 점검 질의서가 파리 MOU에 의해 공표되었다고 안내했다.", "eSum": "DNV advised that the Paris/Tokyo MoU joint CIC on cargo securing starts 1 September 2026 and that the official inspection questionnaire has now been published by the Paris MoU.", "kImp": "질의서를 미리 확보하면 선박은 점검 항목을 사전 자가진단해 대응할 수 있다.", "eImp": "Early access to the questionnaire lets ships self-assess inspection items in advance.", "url": "https://www.dnv.com/news/"}]}, {"code": "COMM", "type": "news", "kTitle": "Section 16. 상업·용선시장", "eTitle": "Section 16. Commercial & Chartering", "items": [{"code": "COMM", "title": "한화, 호주 Austal의 미국 사업부 Austal USA 인수 제안", "src": "The Maritime Executive", "date": "2026-08-10", "kSum": "한화(Hanwha)의 미국 법인이 호주 방산 조선사 Austal의 미국 사업부 Austal USA를 인수하기 위해 10억~12억 달러 규모의 비구속적 제안을 냈다. 2024년 Austal 본사 전체 인수에 실패했던 한화가 미국 방산 조선 확대를 위해 재추진하는 것이다.", "eSum": "Hanwha's U.S. division made a non-binding US$1.0-1.2 billion offer to buy Austal USA, the American operations of Australian shipbuilder Austal Ltd., reviving its failed 2024 bid for the whole group as it expands its U.S. defense shipbuilding footprint.", "kImp": "성사 시 모빌(Alabama) 조선소와 샌디에이고 수리시설, 3,000여 명 인력을 확보해 한화의 미국 방산 조선 입지가 크게 확대되는 대형 M&A다.", "eImp": "A major M&A that, if accepted, would add a Mobile shipyard, a San Diego repair facility and over 3,000 workers, sharply expanding Hanwha's U.S. naval shipbuilding presence.", "url": "https://maritime-executive.com/article/hanwha-offers-to-buy-austal-usa"}, {"code": "COMM", "title": "다이애나쉬핑, 신규 케이프사이즈 용선서 운임 18% 인상 확보", "src": "Splash247", "date": "2026-08-10", "kSum": "그리스 벌커 선사 다이애나쉬핑(Diana Shipping)이 신규 케이프사이즈 용선 계약에서 종전 대비 18%의 운임 인상을 확보했다.", "eSum": "Greek bulker owner Diana Shipping secured an 18% rate increase for a new capesize charter fixture.", "kImp": "케이프사이즈 용선료 상승세를 반영하는 개별 계약으로, 건화물(드라이벌크) 시황 개선 신호로 읽힌다.", "eImp": "The fixture reflects rising capesize charter rates and points to an improving dry bulk market.", "url": "https://splash247.com/diana-adds-to-rate-gains-with-new-capesize-fixture/"}, {"code": "COMM", "title": "유니아시아, 일본서 핸디사이즈 신조 2척으로 확대", "src": "Splash247", "date": "2026-08-10", "kSum": "싱가포르 상장사 유니아시아그룹(Uni-Asia Group)이 일본에서 두 번째 4만 dwt 벌커를 발주하며 핸디사이즈 신조 프로그램을 두 배로 늘렸다. 니혼조선(Nihon Shipyard) 및 계열사와 계약했다.", "eSum": "Singapore-listed Uni-Asia Group has doubled its handysize newbuilding programme in Japan with a second 40,000 dwt bulker, signing with Nihon Shipyard and an affiliate.", "kImp": "일본 조선소를 통한 핸디사이즈 신조 발주 확대는 소형 벌커 선대 교체와 일본 야드 수주 흐름을 보여준다.", "eImp": "The expanded Japanese newbuild order reflects handysize fleet renewal and Japanese yard order momentum.", "url": "https://splash247.com/uni-asia-doubles-up-on-japanese-handysize-newbuilds/"}, {"code": "COMM", "title": "캐스터마리타임, 카므사르막스 선박을 Fearnley 주선 합작사로 이전", "src": "Splash247", "date": "2026-08-10", "kSum": "캐스터마리타임(Castor Maritime)이 카므사르막스 벌커 Magic Starlight를 펀리(Fearnley)가 주선한 합작 벤처로 이전했다.", "eSum": "Castor Maritime has moved its kamsarmax bulker Magic Starlight into a Fearnley-arranged joint venture.", "kImp": "선박을 합작 구조로 이전하는 자산 재배치로, 벌커 선주들의 자본 파트너십 및 선대 운용 전략 변화를 보여준다.", "eImp": "The vessel transfer into a JV illustrates bulker owners' evolving capital partnerships and fleet strategies.", "url": "https://splash247.com/castor-shifts-kamsarmax-into-fearnley-backed-venture/"}, {"code": "COMM", "title": "파나마운하, 엘니뇨 가뭄에 네오파나막스 최대 흘수 추가 축소", "src": "The Maritime Executive", "date": "2026-08-06", "kSum": "파나마운하청(ACP)이 엘니뇨 심화에 따른 가툰호 수위 하락으로 네오파나막스 갑문의 최대 흘수를 8월 26일 48피트, 9월 3일 47.5피트로 낮춘다. 올해 네 번째·다섯 번째 흘수 제한 조치다.", "eSum": "The Panama Canal Authority is cutting the maximum draft at the Neopanamax locks to 48 feet on August 26 and 47.5 feet on September 3 as an intensifying El Nino lowers Gatun Lake - its fourth and fifth draft cuts this year.", "kImp": "컨테이너선·LNG선·탱커의 적재 제한과 평균 6일 이상으로 늘어난 대기시간을 초래할 수 있으며, 호르무즈 해협 폐쇄로 미국 에너지 수출 물량까지 몰리며 운하 혼잡이 가중되고 있다.", "eImp": "The cuts could force cargo limits on containerships, LNG carriers and tankers and lengthen waits (now over six days), compounded by U.S. energy export flows diverted by the Hormuz closure.", "url": "https://maritime-executive.com/article/panama-canal-cuts-drafts-for-largest-ships-as-el-nino-intensifies"}, {"code": "COMM", "title": "카델러, COSCO에 해상풍력 설치선(WTIV) 2척 9억3천만불 추가 발주", "src": "The Maritime Executive", "date": "2026-08-10", "kSum": "카델러(Cadeler)가 중국 COSCO Shipping Offshore 조선소에 약 8억500만 유로(9억3천만 달러) 규모로 잭업식 해상풍력 터빈 설치선(WTIV) 2척을 추가 발주했다.", "eSum": "Cadeler ordered two more jack-up wind turbine installation vessels (WTIV) from China's COSCO Shipping Offshore for about EUR805 million (US$930 million).", "kImp": "해상풍력 설치선 부문의 견조한 수요를 반영하는 대형 신조 발주로, 세계 최대 WTIV 선대를 보유한 카델러의 확장이 지속되고 있다.", "eImp": "A large newbuild order reflecting strong WTIV demand as Cadeler, owner of the largest such fleet, keeps expanding.", "url": "https://maritime-executive.com/article/cadeler-orders-two-more-wtiv-vessels-citing-continued-strong-sector-demand"}]}, {"code": "GEO", "type": "news", "kTitle": "Section 17. 지정학", "eTitle": "Section 17. Geopolitics", "items": [{"code": "GEO", "title": "사상 최대 규모 러시아 선단, 북극항로 따라 동진", "src": "Splash247", "date": "2026-08-10", "kSum": "사상 최대 규모로 추정되는 러시아 선단(convoy)이 북극항로(Northern Sea Route)를 따라 동쪽으로 이동하고 있는 것으로 확인됐다.", "eSum": "What appears to be a record-sized Russian convoy is pushing east along the Arctic Northern Sea Route.", "kImp": "러시아의 북극항로 물동량 확대와 제재 회피성 선대 운용을 보여주는 사례로, 북극 해운의 지정학적 중요성이 커지고 있다.", "eImp": "The convoy highlights Russia's expanding Arctic traffic and sanctions-era fleet use, underscoring the Northern Sea Route's growing geopolitical weight.", "url": "https://splash247.com/russian-armada-pushes-east-through-the-arctic/"}, {"code": "GEO", "title": "후티, 사우디 정유시설 공격…ADNOC 관련 16번째 피해", "src": "Splash247", "date": "2026-08-10", "kSum": "후티(Houthi)가 사우디 정유시설을 공격하면서 ADNOC(아부다비국영석유)이 관련 열여섯 번째 피해를 입었다.", "eSum": "ADNOC suffered its sixteenth hit as Houthis struck a Saudi refinery, extending their campaign against Gulf energy targets.", "kImp": "후티의 홍해·걸프 에너지 인프라 공격이 지속·확대되며 역내 해상·에너지 안보 위협이 고조되고 있다.", "eImp": "The strike shows the Houthis' persistent, widening campaign against Red Sea and Gulf energy infrastructure, raising regional maritime and energy security risks.", "url": "https://splash247.com/adnoc-suffers-sixteenth-hit-as-houthis-strike-saudi-refinery/"}, {"code": "GEO", "title": "러시아 해군, 영국해협 상시 주둔 강화…다크플릿 호위", "src": "The Maritime Executive", "date": "2026-08-05", "kSum": "러시아 프리깃 Neustrashimy(F722)가 영국해협 상주 초계함으로 자리 잡으며, 정보수집함 Vasiliy Tatishchev와 함께 다크플릿(dark fleet) 상선을 감시하고 있다. Ka-27 헬기 탑재도 확인됐다.", "eSum": "The Russian frigate Neustrashimy (F722) has settled in as a permanent picket ship in the English Channel, operating with the intelligence vessel Vasiliy Tatishchev and a Ka-27 helicopter to shadow dark-fleet merchant vessels.", "kImp": "러시아의 영국해협·북해 상시 주둔이 반영구화되며, 그림자 선단 호위와 서방 해군에 대한 감시 부담이 커지고 있다.", "eImp": "Russia's semi-permanent Channel presence increases shadow-fleet escorting and surveillance pressure on Western navies.", "url": "https://maritime-executive.com/article/russian-navy-augments-its-long-term-presence-in-english-channel"}, {"code": "GEO", "title": "러시아, 흑해서 선박 2척 추가 공격…우크라 선원 1명 사망", "src": "The Maritime Executive", "date": "2026-08-06", "kSum": "8월 6일 러시아의 공격으로 흑해에서 선박 2척이 추가 피격되고 우크라이나 선원 1명이 사망했다. 우크라이나는 항만·상선에 대한 거의 매일의 공격에 강력 항의하며, 7월 아조프해·흑해에서 러시아 선박을 사상 최다로 타격했다고 밝혔다.", "eSum": "Two more vessels were struck and at least one Ukrainian seafarer killed in Russian attacks in the Black Sea on August 6; Ukraine protested the near-daily strikes on its ports and shipping while noting it hit a record number of Russian vessels in July.", "kImp": "흑해 곡물·상업 해운에 대한 공격이 격화되며 인명 피해와 항로 리스크가 커지고, 국제사회의 상선 보호 요구가 확산되고 있다.", "eImp": "Escalating attacks on Black Sea commercial shipping are causing casualties and heightening route risk, spurring calls to protect merchant vessels.", "url": "https://maritime-executive.com/article/seafarer-killed-as-russia-strikes-two-more-black-sea-ships"}, {"code": "GEO", "title": "후티, 홍해 캠페인 격화…8번째 사우디 유조선 공격 주장", "src": "gCaptain", "date": "2026-08-05", "kSum": "후티(Houthi)가 사우디 유조선에 대한 또 한 번의 공격 책임을 주장했고, 영국해사무역기구(UKMTO)는 새 경보를 발령했다. 후티의 여덟 번째 사우디 탱커 공격 주장이다.", "eSum": "The Houthis claimed responsibility for another attack on a Saudi oil tanker - their eighth such claim - as UK Maritime Trade Operations (UKMTO) issued a fresh warning.", "kImp": "후티의 홍해 캠페인 격화로 사우디 연계 선박에 대한 위협이 반복되며, 역내 항행 안전과 보험료 부담이 커지고 있다.", "eImp": "The intensifying Houthi Red Sea campaign repeatedly threatens Saudi-linked ships, raising navigation risk and insurance costs.", "url": "https://gcaptain.com/houthis-escalate-red-sea-campaign-claim-eighth-saudi-tanker-attack/"}]}, {"code": "TW", "type": "news", "kTitle": "Section 18. TradeWinds 선박관리", "eTitle": "Section 18. TradeWinds Ship Management", "items": [{"code": "TW", "title": "Charles Barne steps into new CEO role at Lykiardopulo", "src": "TradeWinds", "date": "2026-08-10", "kSum": "그리스 선주 Lykiardopulo(리키아르도풀로)에서 Charles Barne(찰스 반)이 신임 최고경영자(CEO)로 취임한다. (유료 기사, 헤드라인 기준)", "eSum": "Charles Barne takes on the CEO role at Greek shipowner Lykiardopulo (paywalled; headline only).", "kImp": "전통 그리스 선주 가문 경영진 교체는 선대 운용·전략 방향에 영향을 줄 수 있다.", "eImp": "A leadership change at a traditional Greek owner can shape fleet strategy and direction.", "url": "https://www.tradewindsnews.com/people/charles-barne-steps-into-new-ceo-role-at-lykiardopulo/2-1-2026892"}, {"code": "TW", "title": "International Seaways banks record second quarter with bumper $295m profit", "src": "TradeWinds", "date": "2026-08-10", "kSum": "탱커 선사 International Seaways(인터내셔널 시웨이즈)가 2분기 2억9,500만 달러의 기록적 순이익을 발표했다. (유료 기사, 헤드라인 기준)", "eSum": "Tanker owner International Seaways reported a record Q2 profit of $295m (paywalled; headline only).", "kImp": "탱커 시황 강세를 반영한 실적으로, 상장 선사의 배당·재투자 여력을 시사한다.", "eImp": "Strong results reflect a firm tanker market and signal dividend and reinvestment capacity.", "url": "https://www.tradewindsnews.com/tankers/international-seaways-banks-record-second-quarter-with-bumper-295m-profit/2-1-2026949"}, {"code": "TW", "title": "Nova orders two new bulkers in Japan after double S&P play", "src": "TradeWinds", "date": "2026-08-10", "kSum": "Nova Marine Carriers(노바 마린 캐리어스)가 두 건의 S&P 거래에 이어 일본 조선소에 신조 벌커 2척을 발주했다. (유료 기사, 헤드라인 기준)", "eSum": "Nova Marine Carriers ordered two newbuild bulkers at a Japanese yard following a pair of S&P deals (paywalled; headline only).", "kImp": "매각·신조를 병행하는 선대 갱신 전략으로, 자산 회전과 선대 현대화를 동시에 추진한다.", "eImp": "A combined S&P-and-newbuild fleet-renewal move drives asset turnover and modernisation together.", "url": "https://www.tradewindsnews.com/bulkers/nova-marine-carriers-orders-two-new-bulkers-in-japan-after-double-s-p-play/2-1-2025973"}, {"code": "TW", "title": "Four International Seaways newbuildings en route to refreshing Panamax International venture", "src": "TradeWinds", "date": "2026-08-10", "kSum": "International Seaways(인터내셔널 시웨이즈)의 신조선 4척이 Panamax International(파나막스 인터내셔널) 풀 벤처를 재편·강화하는 데 투입될 예정이다. (유료 기사, 헤드라인 기준)", "eSum": "Four International Seaways newbuildings are set to refresh the Panamax International pool venture (paywalled; headline only).", "kImp": "풀 벤처에 신조선 투입은 풀 경쟁력과 수익 배분 구조에 영향을 준다.", "eImp": "Injecting newbuildings into the pool affects its competitiveness and earnings distribution.", "url": "https://www.tradewindsnews.com/finance/four-international-seaways-newbuildings-en-route-to-refreshing-panamax-international-venture/2-1-2027117"}, {"code": "TW", "title": "Minsheng Financial Leasing inks tanker newbuildings against Shell charters", "src": "TradeWinds", "date": "2026-08-10", "kSum": "Minsheng Financial Leasing(민생금융리스)이 Shell(셸) 장기 용선을 배경으로 탱커 신조를 계약했다. (유료 기사, 헤드라인 기준)", "eSum": "Minsheng Financial Leasing ordered tanker newbuildings backed by Shell charters (paywalled; headline only).", "kImp": "메이저 용선 계약을 담보로 한 리스사의 신조 발주는 안정적 현금흐름 기반 선박금융 모델을 보여준다.", "eImp": "A leasing house ordering against major-oil charters illustrates charter-backed ship-finance with stable cash flow.", "url": "https://www.tradewindsnews.com/tankers/minsheng-financial-leasing-inks-tanker-newbuildings-against-shell-charters/2-1-2026865"}, {"code": "TW", "title": "Arne Blystad learns when a day actually ends in row over cancelled tanker sale", "src": "TradeWinds", "date": "2026-08-10", "kSum": "노르웨이 선주 Arne Blystad(아르네 블뤼스타)가 탱커 매각 취소를 둘러싼 S&P 분쟁에 휘말렸다. (유료 기사, 헤드라인 기준)", "eSum": "Norwegian owner Arne Blystad is embroiled in an S&P dispute over a cancelled tanker sale (paywalled; headline only).", "kImp": "매매계약 이행 시점 해석 분쟁은 S&P 거래의 계약 리스크와 관행에 시사점을 준다.", "eImp": "A dispute over contract timing highlights execution risk and practice in S&P deals.", "url": "https://www.tradewindsnews.com/tankers/arne-blystad-learns-when-a-day-actually-ends-in-row-over-cancelled-tanker-sale/2-1-2026912"}, {"code": "TW", "title": "Transworld Shipping Lines expansion plans hamstrung by high vessel prices", "src": "TradeWinds", "date": "2026-08-10", "kSum": "Transworld Shipping Lines(트랜스월드 시핑 라인스)의 선대 확장 계획이 높은 선가에 발목이 잡혔다. (유료 기사, 헤드라인 기준)", "eSum": "Transworld Shipping Lines' fleet expansion is constrained by elevated vessel prices (paywalled; headline only).", "kImp": "고선가 환경이 중소 선사의 성장 전략에 미치는 제약을 보여준다.", "eImp": "It shows how high asset prices constrain growth strategy for mid-sized owners.", "url": "https://www.tradewindsnews.com/containers/transworld-shipping-lines-expansion-plans-hamstrung-by-high-vessel-prices/2-1-2026997"}, {"code": "TW", "title": "Middle East conflict weighs on Regional Container Lines' first half", "src": "TradeWinds", "date": "2026-08-10", "kSum": "중동 분쟁이 Regional Container Lines(리저널 컨테이너 라인스, RCL)의 상반기 실적에 부담으로 작용했다. (유료 기사, 헤드라인 기준)", "eSum": "Middle East conflict weighed on Regional Container Lines' first-half performance (paywalled; headline only).", "kImp": "지정학 리스크가 역내 컨테이너 선사의 항로·수익에 미치는 영향을 반영한다.", "eImp": "It reflects how geopolitical risk hits routing and earnings for a regional container carrier.", "url": "https://www.tradewindsnews.com/containers/middle-east-conflict-weighs-on-regional-container-lines-first-half/2-1-2026903"}, {"code": "TW", "title": "ADNOC L&S bolsters tanker fleet with $1.3bn acquisitions", "src": "Seatrade Maritime", "date": "2026-08-07", "kSum": "ADNOC Logistics & Services(ADNOC 물류·서비스)가 13억 달러 규모 인수를 통해 탱커 선대를 확장했다.", "eSum": "ADNOC Logistics & Services expanded its tanker fleet through $1.3bn in acquisitions.", "kImp": "국영 물류사의 대규모 선대 인수는 중동발 에너지 물류 지배력 강화 흐름을 보여준다.", "eImp": "A large fleet acquisition by the state logistics arm underlines growing Gulf control of energy shipping.", "url": "https://www.seatrade-maritime.com/tankers/adnoc-l-s-bolsters-tanker-fleet-with-1-3bn-acquisition"}]}, {"code": "HOT", "type": "news", "kTitle": "Section 19. 핫이슈: 호르무즈 해협", "eTitle": "Section 19. Hot Topic: Strait of Hormuz", "items": [{"code": "HOT", "title": "트럼프, 이란에 배상 요구…호르무즈 합의 기대 후퇴", "src": "gCaptain", "date": "2026-08-10", "kSum": "트럼프 미 대통령이 8월 10일 이란에 대해 전쟁·공격·시위 과정에서 숨진 사람들에 대한 배상을 요구했다. 호르무즈 해협 재개 합의에 대한 기대가 사그라드는 가운데 나온 발언이다.", "eSum": "On August 10, U.S. President Trump demanded that Iran pay compensation for people he said it had killed in wars, attacks and protests - a move coming as hopes for a Strait of Hormuz deal fade.", "kImp": "미·이란 협상 교착과 호르무즈 재개 지연을 시사하는 발언으로, 해협 정상화와 유가·해상 리스크에 부정적 신호다.", "eImp": "The remarks signal stalled U.S.-Iran talks and delayed Hormuz reopening, a negative for normalization, oil prices and maritime risk.", "url": "https://gcaptain.com/trump-demands-compensation-from-iran-as-hormuz-deal-hopes-fade/"}, {"code": "HOT", "title": "기고: 호르무즈 해협, 국제해양법의 한계를 시험하다", "src": "The Maritime Executive", "date": "2026-08-09", "kSum": "호르무즈 해협을 둘러싼 통항 제도 논쟁을 다룬 기고. UNCLOS 비준국이 아닌 이란은 '무해통항(innocent passage)'을, 미국 등 대다수 해운국은 제38조 '통과통항(transit passage)'을 주장하며, UNCLOS에 강제 이행 장치가 없어 항행의 자유가 시험대에 올랐다고 분석한다.", "eSum": "An op-ed examines the legal dispute over Hormuz: Iran, a non-party to UNCLOS, claims innocent passage, while the U.S. and most maritime nations invoke transit passage under Article 38 - and with no enforcement mechanism in UNCLOS, freedom of navigation is under strain.", "kImp": "법적 불확실성은 항로 계획·전쟁위험 평가·보험료·용선 등 상업적 의사결정으로 직결되어 세계 공급망 안정성에 영향을 준다.", "eImp": "Legal uncertainty translates directly into voyage planning, war-risk assessments, insurance costs and chartering decisions, affecting global supply-chain stability.", "url": "https://maritime-executive.com/editorials/op-ed-strait-of-hormuz-tests-the-limits-of-the-law-of-the-sea"}, {"code": "HOT", "title": "이란, 호르무즈 재개를 美 양보와 연계", "src": "gCaptain", "date": "2026-08-10", "kSum": "이란은 오만과 호르무즈 해협 신규 항로를 규정하는 최종 협정에 근접했다고 밝히면서도, 미국이 여러 요구를 수용해야 한다는 조건을 재차 강조했다.", "eSum": "Iran said it was nearing a final pact with Oman defining new shipping lanes through the Strait of Hormuz, but repeated that the U.S. must first meet several demands.", "kImp": "해협 재개를 미국의 양보와 연계함으로써 협상이 장기화·정치화되고 있으며, 통항 정상화 시점의 불확실성이 지속된다.", "eImp": "Tying reopening to U.S. concessions prolongs and politicizes talks, keeping the timing of normalized transit uncertain.", "url": "https://gcaptain.com/iran-ties-hormuz-reopening-to-us-concessions-on-several-demands/"}, {"code": "HOT", "title": "해운업계, 이란의 호르무즈 통제 구상에 큰 걸림돌 지적", "src": "gCaptain", "date": "2026-08-06", "kSum": "테헤란에 걸프 진입 선박에 대한 통제권을 주는 이란-오만 제안 합의가 실무적으로 쉽지 않다는 분석이 나왔다. 해운업계는 여러 장애물을 지적했다.", "eSum": "A proposed Iran-Oman deal that would give Tehran control over ships entering the Gulf through the Strait of Hormuz is not easily workable, with the shipping industry citing major obstacles.", "kImp": "해협 통제 구상의 현실성에 의문이 제기되며, 통항 관리·주권·통항료 등을 둘러싼 갈등이 지속될 전망이다.", "eImp": "Doubts over the control scheme's feasibility suggest continued friction over transit management, sovereignty and possible tolls.", "url": "https://gcaptain.com/shipping-industry-sees-major-obstacles-to-irans-hormuz-control-plan/"}, {"code": "HOT", "title": "이란, 오만과 호르무즈 항로 원칙적 합의 발표", "src": "gCaptain", "date": "2026-08-06", "kSum": "이란은 오만과의 호르무즈 해협 부분 재개를 위한 제안 항로에 대해 원칙적으로 합의했다고 밝혔으나, 최종 타결을 위한 대기가 이어졌다.", "eSum": "Iran said an agreement with Oman on a proposed Strait of Hormuz shipping route had been reached in principle, though the wait for a final deal continued.", "kImp": "원칙적 합의 발표에도 세부 확정이 지연되며, 해협 부분 재개 시점을 둘러싼 불확실성이 지속되고 있다.", "eImp": "Despite an 'in principle' agreement, unresolved details delay the timing of a partial Hormuz reopening.", "url": "https://gcaptain.com/iran-says-deal-with-oman-on-hormuz-agreed-in-principle/"}]}, {"code": "SYS", "type": "news", "kTitle": "Section 20. 시스템·앱", "eTitle": "Section 20. System & App", "items": [{"code": "SYS", "title": "ADNOC L&S cuts smart port service sourcing from 3 hours to 45 seconds", "src": "The Digital Ship", "date": "2026-08-10", "kSum": "ADNOC Logistics & Services(ADNOC 물류·서비스)가 스마트 포트 서비스 소싱 시간을 기존 3시간에서 45초로 단축한 디지털 솔루션을 도입했다.", "eSum": "ADNOC Logistics & Services deployed a digital solution that cut smart-port service sourcing time from three hours to 45 seconds.", "kImp": "항만 서비스 조달 자동화는 포트콜 비용·지연을 줄이는 실질적 운영 효율화 사례다.", "eImp": "Automating port-service procurement is a concrete efficiency gain that cuts port-call cost and delay.", "url": "https://thedigitalship.com/news/electronics-navigation/adnoc-ls-cuts-smart-port-service-sourcing-from-3-hours-to-45-seconds/"}, {"code": "SYS", "title": "Hapag-Lloyd to launch ODeX payment portal in Angola", "src": "Container News", "date": "2026-08-10", "kSum": "Hapag-Lloyd(하파그로이드)이 앙골라에서 ODeX 디지털 결제·문서 포털을 도입해 현지 화주의 결제 절차를 전자화한다.", "eSum": "Hapag-Lloyd will launch the ODeX digital payment and documentation portal in Angola, digitising payment processes for local customers.", "kImp": "결제·서류 전자화는 신흥시장에서 포트콜·화물 처리의 투명성과 속도를 높인다.", "eImp": "Digitising payments and documents raises transparency and speed of cargo processing in emerging markets.", "url": "https://container-news.com/hapag-lloyd-to-launch-odex-payment-portal-in-angola/"}, {"code": "SYS", "title": "ZeroNorth launches Propel agentic AI platform for maritime operations", "src": "Container News", "date": "2026-08-10", "kSum": "ZeroNorth(제로노스)가 항해·선박·연료 관리 워크플로 전반의 운영 업무를 자동화하는 에이전틱 AI 애플리케이션 'Propel'을 출시했다.", "eSum": "ZeroNorth launched Propel, an agentic AI application designed to automate operational tasks across voyage, vessel and fuel management workflows.", "kImp": "에이전틱 AI의 상용 도입은 해운 운영 자동화의 다음 단계로, 의사결정 지원에서 실행 자동화로 이동한다.", "eImp": "Commercial rollout of agentic AI marks the next step in shipping automation, moving from decision support toward task execution.", "url": "https://container-news.com/zeronorth-launches-propel-agentic-ai-platform-for-maritime-operations/"}]}, {"code": "SMGR", "type": "news", "kTitle": "Section 21. 선박관리사", "eTitle": "Section 21. Ship Managers", "items": [{"code": "SMGR", "title": "Fleet Care by the Numbers: Supporting Seafarers Before Challenges Become Crises", "src": "Fleet Management (Caravel Group)", "date": "2026-08-04", "kSum": "Fleet Management(플리트 매니지먼트)이 선원 복지 프로그램 'Fleet Care'를 데이터로 소개하며, 문제가 위기로 번지기 전 조기·선제적 지원이 어떻게 이뤄지는지 설명했다.", "eSum": "Fleet Management detailed its 'Fleet Care' seafarer welfare programme, showing how early, data-driven support to crew helps prevent issues from escalating into crises.", "kImp": "선제적 선원 복지·정신건강 지원은 이직률과 사고 리스크를 낮추는 관리사의 차별화 요소다.", "eImp": "Proactive crew welfare and mental-health support is a differentiator that lowers turnover and incident risk for a manager.", "url": "https://www.fleetship.com/media"}]}]};